#!/usr/bin/env bash
# SKYBYTE Manager V2.1 community manager; review before running, Debian/Ubuntu only
# Generated by scripts/build.py from src/. Edit source modules, then rebuild.
# The ownership marker above stays stable across manager releases.
# Installation/restore deliberately isolate transactions in subshells; dynamic locals
# remain visible to called helpers/traps and never escape to menu operations.
# shellcheck disable=SC2030,SC2031
set -Eeuo pipefail
umask 077
SCRIPT_PATH="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/$(basename -- "${BASH_SOURCE[0]}")"
MANAGER_VERSION=2.8.13
CORE_RECOMMENDED=1.14.3
BASE=/etc/singbox-v2
CONF=/etc/sing-box/config.json
SYSTEMD_DIR=/etc/systemd/system
OS_RELEASE=/etc/os-release
MANAGER_BIN=/usr/local/sbin/singbox-v2
MANAGER_LIB=/usr/local/lib/singbox-v2/singbox-v2.sh
SYSCTL_FILE=/etc/sysctl.d/90-singbox-v2-bbr.conf
META=$BASE/state.json
REPORT=$BASE/reports
BACKUP=$BASE/backups
BIN=/usr/local/bin/sing-box
LOCK=/run/singbox-v2.lock
WARP_REPO_FILE=/etc/apt/sources.list.d/skybyte-cloudflare-warp.list
WARP_KEY_FILE=/usr/share/keyrings/skybyte-cloudflare-warp.gpg
HAPROXY_BIN=/usr/sbin/haproxy
HAPROXY_RUNTIME_DIR=/run/systemd/system

# Language preference is independent of sing-box configuration.
LANG_FILE="$BASE/language.conf"
LANGUAGE_CHOICE=""
load_language() {
  if [[ -f "$LANG_FILE" ]]; then
    local value
    value=$(cat "$LANG_FILE")
    case "$value" in zh_CN|en_US) LANGUAGE_CHOICE=$value;; esac
  fi
}
select_language() {
  local choice
  while :; do
    printf '%s\n========== Language / 语言 ==========\n 1. 简体中文\n 2. English\n=======================================\n%s' "$GREEN" "$RESET"
    prompt_read '请选择语言 / Select language [1/2]: ' choice || return 1
    case "$choice" in 1) LANGUAGE_CHOICE=zh_CN;; 2) LANGUAGE_CHOICE=en_US;; *) continue;; esac
    printf '%s\n' "$LANGUAGE_CHOICE" > "$LANG_FILE"
    chmod 600 "$LANG_FILE"
    break
  done
}
# Keep input prompts green, resetting before the user types. Hidden token input stays hidden.
prompt_read(){
 if [[ ${3:-} == secret ]]; then read -rs -p "${GREEN}$1${RESET}" "$2"
 else read -r -p "${GREEN}$1${RESET}" "$2"; fi
}
prompt_options(){ printf '%s%s%s\n' "$GREEN" "$(L "$1" "$2")" "$RESET"; }
say(){ printf '%s\n' "$(L "$1" "$2")"; }
L() { if [[ "$LANGUAGE_CHOICE" == en_US ]]; then printf '%s' "$2"; else printf '%s' "$1"; fi; }
if [[ -t 1 && -z "${NO_COLOR:-}" ]]; then
 GREEN=$'\033[1;32m'; RED=$'\033[1;31m'; YELLOW=$'\033[1;33m'; CYAN=$'\033[1;36m'; RESET=$'\033[0m'
else GREEN=''; RED=''; YELLOW=''; CYAN=''; RESET=''; fi
YOUTUBE='https://www.youtube.com/@SKYBYTE9119'
ok(){ printf '%s✔ %s%s\n' "$GREEN" "$*" "$RESET"; }
warn(){ printf '%s⚠ %s%s\n' "$YELLOW" "$*" "$RESET"; }
err(){ printf '%s✖ %s%s\n' "$RED" "$*" "$RESET" >&2; }
# APT compatibility helpers. Archive conversion only targets official Bullseye entries.
APT_ROOT=${APT_ROOT:-/etc/apt}
apt_archive_filter(){
 local format=$1 file=$2
 awk -v format="$format" '
 function official(uri) {return uri ~ /^https?:\/\/(deb|security|ftp)\.debian\.org\/debian(-security)?\/?$/}
 # Keep the existing transport: minimal Bullseye images may not yet have CA roots.
 # APT still verifies the signed Release and package hashes over either transport.
 function archived(uri) {sub(/\/\/(deb|security|ftp)\.debian\.org/,"//archive.debian.org",uri);return uri}
 function listline(line, code,tail,hash,prefix,rest,option,end,fields,count,i,url,suite) {
  hash=index(line,"#");code=hash?substr(line,1,hash-1):line;tail=hash?substr(line,hash):""
  if (code !~ /^[ \t]*deb(-src)?[ \t]+/) return line
  match(code,/^[ \t]*deb(-src)?[ \t]+/);prefix=substr(code,1,RLENGTH);rest=substr(code,RLENGTH+1);option=""
  if (substr(rest,1,1)=="[") {end=index(rest,"]");if(!end)return line;option=substr(rest,1,end);rest=substr(rest,end+1);sub(/^[ \t]+/,"",rest)}
  count=split(rest,fields,/[ \t]+/);url=fields[1];suite=fields[2]
  if (!official(url) || suite !~ /^bullseye(-security|-updates)?$/) return line
  if ((suite=="bullseye-security") != (url ~ /debian-security\/?$/)) return line
  if (option=="") option="[check-valid-until=no]"
  else if (option ~ /check-valid-until=/) sub(/check-valid-until=[^] \t]+/,"check-valid-until=no",option)
  else sub(/\]$/," check-valid-until=no]",option)
  sub(url,archived(url),rest);changed=1
  return prefix option " " rest tail
 }
 function stanza(record,parts,n,i,field,value,uris,suites,enabled,u,s,num,active,out,line,validity) {
  n=split(record,parts,"\n");uris="";suites="";enabled="";field=""
  for(i=1;i<=n;i++) {
   line=parts[i];if(line ~ /^[ \t]*#/)continue
   if(line ~ /^[A-Za-z-]+:/) {field=tolower(line);sub(/:.*/,"",field);value=line;sub(/^[^:]+:[ \t]*/,"",value)}
   else if(line ~ /^[ \t]+/) {value=line;sub(/^[ \t]+/,"",value)} else {field="";continue}
   if(field=="uris")uris=uris " " value
   if(field=="suites")suites=suites " " value
   if(field=="enabled")enabled=tolower(value)
  }
  if(enabled=="no" || uris=="" || suites=="")return record
  sub(/^ +/,"",uris);sub(/^ +/,"",suites)
  num=split(uris,u,/[ \t]+/);for(i=1;i<=num;i++)if(!official(u[i]) || (u[i] ~ /debian-security\/?$/) != (u[1] ~ /debian-security\/?$/))return record
  num=split(suites,s,/[ \t]+/);for(i=1;i<=num;i++)if(s[i] !~ /^bullseye(-security|-updates)?$/)return record
  for(i=1;i<=num;i++)if((s[i]=="bullseye-security") != (u[1] ~ /debian-security\/?$/))return record
  out="";field="";validity=0
  for(i=1;i<=n;i++) {
   line=parts[i]
   if(line ~ /^[A-Za-z-]+:/) {field=tolower(line);sub(/:.*/,"",field)}
   else if(line !~ /^[ \t]+/)field=""
   if(field=="uris")gsub(/\/\/(deb|security|ftp)\.debian\.org/,"//archive.debian.org",line)
   if(field=="check-valid-until") {if(line ~ /^[A-Za-z-]+:/)line="Check-Valid-Until: no";else continue;validity=1}
   out=out (out==""?"":"\n") line
  }
  if(!validity)out=out "\nCheck-Valid-Until: no"
  changed=1;return out
 }
 BEGIN {if(format=="sources"){RS="";ORS="\n\n"}}
 {if(format=="sources")print stanza($0);else print listline($0)}
 END {if(!changed)exit 10}
 ' "$file"
}
apt_prepare_archive() (
 local id version file format temp result backup_dir='' relative
 id=$(awk -F= '$1=="ID" {gsub(/"/,"",$2);print $2}' "$OS_RELEASE") || return 1
 version=$(awk -F= '$1=="VERSION_ID" {gsub(/"/,"",$2);print $2}' "$OS_RELEASE") || return 1
 [[ $id == debian && $version == 11 ]] || return 0
 [[ ! -L $APT_ROOT && ! -L $APT_ROOT/sources.list.d ]] || { err "$(L 'APT 源目录是符号链接，拒绝修改' 'APT source directory is a symlink; refusing changes')";return 1; }
 local files=()
 [[ ! -e $APT_ROOT/sources.list && ! -L $APT_ROOT/sources.list ]] || files+=("$APT_ROOT/sources.list")
 shopt -s nullglob
 files+=("$APT_ROOT"/sources.list.d/*.list "$APT_ROOT"/sources.list.d/*.sources)
 # Inspect every source path before changing any of them.
 for file in ${files[@]+"${files[@]}"};do
  [[ -f $file && ! -L $file ]] || { err "$(L 'APT 源文件异常，拒绝修改' 'Unsafe APT source file; refusing changes')";return 1; }
 done
 for file in ${files[@]+"${files[@]}"};do
  format=${file##*.}
  temp=$(mktemp "$file.skybyte.XXXXXX") || return 1
  cp -p -- "$file" "$temp" || { rm -f -- "$temp";return 1; }
  if apt_archive_filter "$format" "$file" > "$temp";then result=0;else result=$?;fi
  if [[ $result == 10 ]];then rm -f -- "$temp";continue;fi
  if [[ $result != 0 ]];then rm -f -- "$temp";return "$result";fi
  if [[ -z $backup_dir ]];then
   backup_dir=$(mktemp -d "$APT_ROOT/skybyte-source-backup.XXXXXX") || { rm -f -- "$temp";return 1; }
   chmod 700 "$backup_dir" || return 1
  fi
  if [[ $file == "$APT_ROOT/sources.list" ]];then relative=sources.list;else relative="parts/${file##*/}";fi
  if ! mkdir -p "$backup_dir/$(dirname "$relative")" || ! cp -p -- "$file" "$backup_dir/$relative";then rm -f -- "$temp";return 1;fi
  if ! mv -f -- "$temp" "$file";then rm -f -- "$temp";return 1;fi
 done
 if [[ -n $backup_dir ]];then
  warn "$(L 'Debian 11 官方源已迁至归档；原文件已备份：' 'Official Debian 11 sources moved to archive; originals backed up: ')$backup_dir"
  warn "$(L '归档不提供新的官方安全更新；请规划升级系统。' 'The archive supplies no new official security updates; plan an OS upgrade.')"
 fi
)
apt_refresh(){
 apt_prepare_archive || return 1
 if ! apt-get -o APT::Update::Error-Mode=any -o Acquire::Retries=2 --allow-releaseinfo-change-suite update;then
  err "$(L '软件源索引更新失败，已停止安装；请检查上面的 DNS、签名或源地址错误。' 'Repository index refresh failed; installation stopped. Check DNS, signatures and source URLs above.')"
  return 1
 fi
}
apt_install() (
 local log status
 apt_refresh || return 1
 log=$(mktemp "${TMPDIR:-/tmp}/skybyte-apt.XXXXXX") || return 1
 trap 'rm -f -- "$log"' EXIT
 if DEBIAN_FRONTEND=noninteractive apt-get install -y "$@" > "$log" 2>&1;then cat "$log";return 0;else status=$?;fi
 cat "$log"
 if grep -Eq '404[[:space:]]|404[[:space:]]+Not Found|Failed to fetch' "$log";then
  warn "$(L '安装包下载失败，刷新索引并重试一次。' 'Package download failed; refreshing indexes and retrying once.')"
  apt_refresh || return 1
  # Some archive CDN edges cache an earlier 404 even while the package exists.
  DEBIAN_FRONTEND=noninteractive apt-get install -y "$@" -o Acquire::http::No-Cache=true -o Acquire::https::No-Cache=true || return 1
 else return "$status";fi
)
# Own only /usr/local/bin/sb; never replace the system lrzsz sender at /usr/bin/sb.
MANAGER_SHORTCUT=${MANAGER_SHORTCUT:-/usr/local/bin/sb}
SB_FILE_SENDER=${SB_FILE_SENDER:-/usr/bin/sb}
manager_shortcut_install(){
 require_cmd python3 || return 1
 python3 - "$SCRIPT_PATH" "$MANAGER_LIB" "$MANAGER_SHORTCUT" "$SB_FILE_SENDER" <<'PY_SHORTCUT'
import os,pathlib,shlex,subprocess,sys,tempfile
source,target,shortcut,sender=map(pathlib.Path,sys.argv[1:])
marker='# SKYBYTE Manager shortcut v1\n'
for p in (target,shortcut):
 if not p.is_absolute() or any(x.is_symlink() for x in (p,*p.parents)):
  raise SystemExit('Unsafe shortcut path / 快捷入口路径异常')
 if p.exists() and not p.is_file():raise SystemExit('Existing path is not a regular file')
if shortcut.exists() and not shortcut.read_text().startswith('#!/usr/bin/env bash\n'+marker):
 raise SystemExit('Existing sb command preserved / 已有 sb 命令非本工具，已保留')
if target.exists() and not any(line.startswith('# SKYBYTE Manager V2.1 community manager;') for line in target.read_text().splitlines()[:4]):
 raise SystemExit('Existing manager is not owned / 已有管理脚本归属异常')
if source.is_symlink() or not source.is_file():raise SystemExit('Invalid source manager')
if not any(line.startswith('# SKYBYTE Manager V2.1 community manager;') for line in source.read_text().splitlines()[:4]):raise SystemExit('Unknown source manager')
if not sender.is_absolute() or sender==shortcut:raise SystemExit('Invalid file-sender path')
if subprocess.run(['bash','-n',str(source)]).returncode:raise SystemExit('Invalid manager syntax')
def atomic(p,data,mode):
 p.parent.mkdir(parents=True,exist_ok=True)
 fd,name=tempfile.mkstemp(prefix='.skybyte-',dir=p.parent)
 try:
  os.fchmod(fd,mode)
  with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
  os.replace(name,p)
 finally:
  if os.path.exists(name):os.unlink(name)
if source.absolute()!=target.absolute():
 data=source.read_bytes()
 if not target.exists() or target.read_bytes()!=data or target.stat().st_mode&0o7777!=0o700:atomic(target,data,0o700)
# lrzsz is still available with arguments. Nothing changes /usr/bin/sb.
wrapper='#!/usr/bin/env bash\n'+marker+'set -e\n'
wrapper+='if (( $# )); then\n if [[ -x '+shlex.quote(str(sender))+' ]]; then exec '+shlex.quote(str(sender))+' "$@"; fi\n'
wrapper+=' printf "sb opens SKYBYTE Manager; original file sender unavailable\\n" >&2\n exit 2\nfi\n'
wrapper+='exec bash '+shlex.quote(str(target))+'\n'
data=wrapper.encode()
if not shortcut.exists() or shortcut.read_bytes()!=data or shortcut.stat().st_mode&0o7777!=0o755:atomic(shortcut,data,0o755)
PY_SHORTCUT
}
manager_shortcut_remove(){
 [[ ! -L $MANAGER_SHORTCUT ]] || return 0
 if [[ -f $MANAGER_SHORTCUT ]] && grep -Fxq '# SKYBYTE Manager shortcut v1' "$MANAGER_SHORTCUT";then rm -f -- "$MANAGER_SHORTCUT";fi
}
need_root(){ [[ $EUID == 0 ]] || { err "$(L '需要 root 权限' 'Root privileges required')"; exit 1; }; }
confirm(){ local answer; prompt_read "$1 [y/N]: " answer || return 1; [[ $answer =~ ^[[:space:]]*[Yy][[:space:]]*$ ]]; }
startup_probe(){
 # coreutils timeout is standard on supported Ubuntu/Debian systems. If absent,
 # omit optional information rather than launch an unbounded startup query.
 command -v timeout >/dev/null || return 124
 timeout --kill-after=1s 2s "$@" 2>/dev/null
}
startup_service_info(){
 local label=$1 installed=$2 unit=$3 value snapshot=${4:-} state
 if (( $# < 4 )); then snapshot=$(startup_probe systemctl show --no-pager --property=Id,LoadState,ActiveState "$unit") || snapshot=''; fi
 state=$(awk -v unit="$unit" 'BEGIN {RS="";FS="\n"} {id="";active="";for(i=1;i<=NF;i++){if($i=="Id="unit)id=unit;if($i~/^ActiveState=/)active=substr($i,13)}if(id==unit){print active;exit}}' <<< "$snapshot")
 case $state in
 active|reloading) value=$(L '运行中' 'Running');;
 failed) value=$(L '运行失败' 'Failed');;
 activating) value=$(L '启动中' 'Starting');;
 deactivating) value=$(L '停止中' 'Stopping');;
 inactive) if [[ $installed == true ]]; then value=$(L '已安装，未运行' 'Installed, inactive'); else value=$(L '未安装' 'Not installed'); fi;;
 *) if [[ $installed == true ]]; then value=$(L '已安装，状态未知' 'Installed, status unknown'); else value=$(L '未安装' 'Not installed'); fi;;
 esac
 printf '  %s: %s\n' "$label" "$value"
}
startup_info(){
 local os kernel arch virtual ipv4 ipv6 addresses services sb=false argo=false nginx=false users=false hp=false cert_info
 # shellcheck disable=SC1090
 os=$( ( . "$OS_RELEASE"; printf '%s' "${PRETTY_NAME:-${ID:-}}" ) 2>/dev/null) || os=''
 os=${os:-$(L '未知' 'Unknown')}
 kernel=$(uname -r 2>/dev/null) || kernel=$(L '未知' 'Unknown')
 arch=$(uname -m 2>/dev/null) || arch=$(L '未知' 'Unknown')
 case $arch in x86_64) arch=amd64;; aarch64) arch=arm64;; esac
 virtual=$(L '未知' 'Unknown')
 if command -v systemd-detect-virt >/dev/null; then virtual=$(startup_probe systemd-detect-virt) || virtual=${virtual:-$(L '未知' 'Unknown')}; fi
 ipv4=''; ipv6=''
 if command -v ip >/dev/null; then
  addresses=$(startup_probe ip -o addr show scope global) || addresses=''
  ipv4=$(awk '$3=="inet" {print $4}' <<< "$addresses" | paste -sd ', ' -)
  ipv6=$(awk '$3=="inet6" {print $4}' <<< "$addresses" | paste -sd ', ' -)
 fi
 [[ ! -x $BIN ]] || sb=true
 if [[ -x $BASE/cloudflared ]] || command -v cloudflared >/dev/null; then argo=true; fi
 if command -v nginx >/dev/null; then nginx=true; fi
 services=$(startup_probe systemctl show --no-pager --property=Id,LoadState,ActiveState sing-box.service skybyte-argo-tunnel.service nginx.service skybyte-haproxy.service skybyte-users.service) || services=''
 printf '%s\n----------------------------------------------\n' "$GREEN"
 say "脚本版本：SKYBYTE Manager v$MANAGER_VERSION" "Script version: SKYBYTE Manager v$MANAGER_VERSION"
 say '功能更新：受限网络部署（a → 6）、独立 Argo、IPv6/NAT、WARP 双栈与流媒体地区线索识别' 'Features: restricted-network deployment (a → 6), standalone Argo, IPv6/NAT, WARP dual-stack and media region clues'
 say '系统信息：' 'System information:'
 printf '  %s: %s\n' "$(L '操作系统' 'OS')" "$os" "$(L '内核' 'Kernel')" "$kernel" "$(L '处理器架构' 'Architecture')" "$arch" "$(L '虚拟化' 'Virtualization')" "$virtual"
 printf '  IPv4: %s\n  IPv6: %s\n' "${ipv4:-$(L '未检测到' 'Not detected')}" "${ipv6:-$(L '未检测到' 'Not detected')}"
 startup_service_info sing-box "$sb" sing-box.service "$services"
 startup_service_info Argo "$argo" skybyte-argo-tunnel.service "$services"
 startup_service_info Nginx "$nginx" nginx.service "$services"
 [[ ! -d $BASE/haproxy ]] || hp=true
 startup_service_info 'HAProxy TCP' "$hp" skybyte-haproxy.service "$services"
 [[ ! -f $BASE/users.json ]] || users=true
 startup_service_info "$(L '用户配额服务' 'User quota supervisor')" "$users" skybyte-users.service "$services"
 say 'IP 为本机网卡地址，可能与公网出口不同。' 'IPs are local interface addresses; they may differ from public egress.'
 printf '%s\n' "$RESET"
 if [[ -f $CONF ]] && command -v openssl >/dev/null; then cert_info=$(certificate_info) || cert_info=$(L '证书检查失败' 'Certificate check failed'); [[ -z $cert_info ]] || warn "$cert_info"; fi
}

notice(){ if [[ "$LANGUAGE_CHOICE" == en_US ]]; then cat <<'EOF_EN'
[LEGAL & PRIVACY NOTICE] Use only for lawful networking education and server administration. You must comply with applicable law and service terms. Updating software or changing firewall/network settings may interrupt service or cause data loss; make backups first. Provided as-is to the extent permitted by law. Third-party components retain their licenses.
Installation and updates can contact sky9119.cc (Cloudflare HTTPS redirects), github.com, api.github.com and GitHub release CDNs; these services can see your source IP. Installation queries api.ipify.org/api64.ipify.org for your public address. Optional ACME contacts Let's Encrypt and, for DNS validation, Cloudflare; public certificates disclose domain names. HTTPS subscriptions serve personal credential exports only to token holders. Optional streaming probes contact the selected platforms; WARP installation/tests contact Cloudflare. Those services can see the egress IP and request metadata. Reports stay local in /etc/singbox-v2/reports; manage retention yourself. WARP sends selected traffic through Cloudflare. No developer telemetry or intentional upload of node credentials. Weekly automatic updates have been removed. HY2 requires TLS. A no-domain self-signed certificate mode is available, but clients must securely trust the certificate.
Optional Argo connects to Cloudflare, which terminates outer TLS and can inspect WebSocket payloads. Tunnel tokens are stored locally and included in private backups.
EOF_EN
else cat <<'EOF'
【法律与隐私披露】此工具仅供合法网络技术学习和服务器管理；使用者应遵守适用法律和服务条款。更改防火墙、网络参数及更新软件可能导致中断或损失，请提前备份。软件按现状提供，不排除依法不得排除的责任。第三方软件遵循其许可证。
安装/更新可能连接：sky9119.cc（Cloudflare HTTPS 跳转）、github.com、api.github.com、GitHub 发布文件 CDN，访问服务会暴露请求来源 IP。可选 ACME 会访问 Let's Encrypt，DNS 验证还访问 Cloudflare；公开证书会披露域名。HTTPS订阅仅向持有Token者返回个人客户端凭据。安装时 api.ipify.org/api64.ipify.org 用于识别公网地址；可选流媒体检测访问对应平台，WARP 安装/检测访问 Cloudflare。第三方可能记录出口 IP、查询目标和请求时间。报告保存在本地 /etc/singbox-v2/reports，请自行清理。WARP 将选定流量交由 Cloudflare 转发。无开发者遥测或上传节点密钥；请勿公开包含凭据的配置和导出文件。每周自动更新已移除。HY2 必须有 TLS 证书，无域名用户可生成自签名证书，客户端必须正确配置信任，不能默认跳过证书验证。
可选 Argo 连接 Cloudflare，外层 TLS 在其边缘终止，可检查 WebSocket 载荷。隧道 Token 保存在本地并包含在私密备份中。
EOF
fi
}
require_cmd(){ command -v "$1" >/dev/null || { err "$(L "缺少命令 $1" "Missing command: $1")"; return 1; }; }
valid_port(){ [[ $1 =~ ^[0-9]{1,5}$ ]] && (( 1 <= 10#$1 && 10#$1 <= 65535 )); }
state(){ python3 - "$META" "$1" <<'PY'
import json,sys
with open(sys.argv[1]) as f: d=json.load(f)
print(d.get(sys.argv[2],''))
PY
}
protocol_mode(){
 python3 - "$CONF" <<'PY'
import json,sys
p={i['type'] for i in json.load(open(sys.argv[1]))['inbounds']}
if {'vless','hysteria2'} <= p: print('3')
elif 'vless' in p: print('1')
elif 'hysteria2' in p: print('2')
else: raise ValueError('No supported installed protocols')
PY
}
check_owned(){
 [[ -f $META && -f $CONF ]] || { err "$(L '未发现由本脚本部署的节点' 'No deployment managed by this script was found')"; return 1; }
 local owned_path
 for owned_path in "$BASE" "$META" "$CONF" "$BIN" "$BACKUP" "$(dirname "$CONF")";do
  [[ ! -L $owned_path ]] || { err "$(L '托管路径是符号链接，拒绝修改' 'Managed path is a symlink; refusing changes')";return 1; }
 done
}
backup(){
 check_owned || return 1
 local path file
 users_guard && warp_guard && acme_guard && online_guard && haproxy_guard || return 1
 path="$BACKUP/$(date +%Y%m%d-%H%M%S)-$RANDOM"
 mkdir -m 700 "$path" "$path/config" || return 1
 cp "$CONF" "$path/config/config.json" || return 1
 cp "$META" "$path/state.json" || return 1
 cp "$BIN" "$path/sing-box.bin" || return 1
 if [[ -f "$BASE/hop.nft" ]]; then cp "$BASE/hop.nft" "$path/hop.nft" || return 1; fi
 for file in argo-state.json argo-server.json argo-empty.yml argo.token warp-state.json warp-gateway.json warp-client.json warp-rules.json warp-rules.previous.json core-version.json hop-iptables.sh; do
  if [[ -f $BASE/$file ]]; then cp "$BASE/$file" "$path/$file" || return 1; fi
 done
 if [[ -f $SYSTEMD_DIR/skybyte-warp-gateway.service ]]; then
  cp "$SYSTEMD_DIR/skybyte-warp-gateway.service" "$path/warp-gateway.unit" || return 1
