 fi
 if [[ -f $BASE/argo-state.json && -f $BASE/cloudflared ]]; then cp "$BASE/cloudflared" "$path/cloudflared.bin" || return 1; fi
 python3 - "$path" "$CONF" <<'PY' || return 1
import json,sys,shutil,pathlib
