for i in cfg['inbounds']:
 if i['type']=='hysteria2':
  for field,name in [('certificate_path','hy2-backup.crt'),('key_path','hy2-backup.key')]:
   shutil.copyfile(i['tls'][field],root/'config'/name)
   i['tls'][field]=str(pathlib.Path(sys.argv[2]).parent/name)
  meta['cert_path']=i['tls']['certificate_path']
  meta['managed_certificates']=[i['tls']['certificate_path'],i['tls']['key_path']]
(root/'config'/'config.json').write_text(json.dumps(cfg,indent=2))
(root/'state.json').write_text(json.dumps(meta,indent=2))
PY
 if [[ -f $BASE/users.json ]]; then users_engine backup "$path" || return 1; fi
 if [[ -f $BASE/acme-state.json ]];then cp "$BASE/acme-state.json" "$path/acme-state.json" || return 1;fi
 if [[ -d $BASE/acme ]];then cp -aL "$BASE/acme" "$path/acme" || return 1;fi
 if [[ -f $BASE/subscriptions.json ]];then
  python3 - "$BASE/subscriptions.json" "$path" "$BASE" <<'PY_SUB_BACKUP' || return 1
import json,pathlib,shutil,sys
s=json.load(open(sys.argv[1]));root=pathlib.Path(sys.argv[2]);base=pathlib.Path(sys.argv[3])
for field,name in [('cert','subscription-backup.crt'),('key','subscription-backup.key')]:
 shutil.copyfile(s[field],root/name);(root/name).chmod(0o600);s[field]=str(base/name)
(root/'subscriptions.json').write_text(json.dumps(s,indent=2));(root/'subscriptions.json').chmod(0o600)
PY_SUB_BACKUP
  if [[ -f $SYSTEMD_DIR/skybyte-subscriptions.service ]];then cp "$SYSTEMD_DIR/skybyte-subscriptions.service" "$path/subscriptions.unit" || return 1;fi
  if systemctl is-active --quiet skybyte-subscriptions.service;then echo true > "$path/subscriptions.active";else echo false > "$path/subscriptions.active";fi
 fi
 if [[ -d $BASE/haproxy ]];then haproxy_engine backup "$path/haproxy" >/dev/null || return 1;fi
 backup_engine manifest "$path" || return 1
 chmod -R go-rwx "$path" || return 1; printf '%s\n' "$path"
}
validate_certificate(){
 local cert=$1 key=$2 name=$3 certpub keypub
 LC_ALL=C openssl x509 -in "$cert" -noout -checkend 0 >/dev/null || { err "$(L '证书无效或已过期' 'Certificate invalid or expired')"; return 1; }
 if python3 - "$name" <<'PY_NAME_IP'
import ipaddress,sys
try:ipaddress.ip_address(sys.argv[1])
except ValueError:sys.exit(1)
PY_NAME_IP
 then
  LC_ALL=C openssl x509 -in "$cert" -noout -checkip "$name" | grep -q "does match" || { err "$(L '证书 IP 不匹配' 'Certificate IP does not match')"; return 1; }
 else
  LC_ALL=C openssl x509 -in "$cert" -noout -checkhost "$name" | grep -q "does match" || { err "$(L '证书域名不匹配' 'Certificate hostname does not match')"; return 1; }
 fi
 certpub=$(openssl x509 -in "$cert" -pubkey -noout) || return 1
 keypub=$(openssl pkey -in "$key" -pubout -passin pass: 2>/dev/null) || return 1
 [[ $certpub == "$keypub" ]] || { err "$(L '证书和私钥不匹配' 'Certificate and private key do not match')"; return 1; }
}
# Download only a verified release binary; never execute a package installer on updates.
download_binary(){
 local version=$1 target=$2 arch tmp asset sum
 [[ $version =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
 arch=$(rescue_engine arch "$(uname -m)" sing-box) || return 1
 if [[ -n ${SKYBYTE_ASSET_DIR:-} ]];then rescue_engine asset "$SKYBYTE_ASSET_DIR" sing-box "$version" "$(uname -m)" "$target";return $?;fi
 tmp=$(mktemp -d) || return 1
 asset="sing-box-$version-linux-$arch.tar.gz"
 if ! curl -q -fsSL --connect-timeout 10 --proto '=https' --proto-redir '=https' --retry 2 --max-time 180 "https://github.com/SagerNet/sing-box/releases/download/v$version/$asset" -o "$tmp/$asset" ||
    ! curl -q -fsSL --connect-timeout 10 --proto '=https' --proto-redir '=https' --retry 2 --max-time 30 "https://api.github.com/repos/SagerNet/sing-box/releases/tags/v$version" -o "$tmp/release.json"; then rm -rf "$tmp"; return 1; fi
 sum=$(python3 - "$tmp/release.json" "$asset" <<'PY'
import json,sys
r=json.load(open(sys.argv[1])); assert not r['draft'] and not r['prerelease']
a=next(a for a in r['assets'] if a['name']==sys.argv[2])
digest=a.get('digest') or ''; assert digest.startswith('sha256:')
print(digest.split(':',1)[1])
PY
 ) || { rm -rf "$tmp"; return 1; }
 if [[ ! $sum =~ ^[a-fA-F0-9]{64}$ ]] || ! printf '%s  %s\n' "$sum" "$tmp/$asset" | sha256sum -c - >/dev/null; then rm -rf "$tmp"; return 1; fi
 tar -xzf "$tmp/$asset" -C "$tmp" || { rm -rf "$tmp"; return 1; }
 command install -m 755 "$tmp/sing-box-$version-linux-$arch/sing-box" "$target"
 local rc=$?; rm -rf "$tmp"; return "$rc"
}
setup_service(){ cat >"$SYSTEMD_DIR/sing-box.service" <<EOF
[Unit]
Description=sing-box (managed by singbox-v2)
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$BIN run -c $CONF
Restart=on-failure
RestartSec=3
LimitNOFILE=1048576
[Install]
WantedBy=multi-user.target
EOF
 systemctl daemon-reload; }
# Installation requires a clean deployment; configuration generation is separately testable.
choose_node_name(){
 local value
 prompt_read "$(L '节点名称前缀 [SKYBYTE]（回车默认）：' 'Node name prefix [SKYBYTE] (Enter for default): ')" value || return 1
 python3 - "$value" <<'PY'
import sys,unicodedata
name=sys.argv[1].strip() or 'SKYBYTE'
if len(name)>64 or any(unicodedata.category(c).startswith('C') for c in name):
 print('节点名称最多 64 个字符且不能包含控制字符 / Maximum 64 characters; no control characters',file=sys.stderr)
 sys.exit(1)
print(name)
PY
}
rename_node(){
 check_owned || return 1
 local name
 name=$(choose_node_name) || { err "$(L '节点名称无效' 'Invalid node name')"; return 1; }
 python3 - "$META" "$name" <<'PY'
import json,sys,os,tempfile
p,name=sys.argv[1:];state=json.load(open(p));state['node_name']=name
with tempfile.NamedTemporaryFile(mode='w',dir=os.path.dirname(p),delete=False) as f:
 json.dump(state,f,ensure_ascii=False,indent=2);temp=f.name
os.chmod(temp,0o600);os.replace(temp,p)
PY
 if [[ -f $BASE/argo-state.json ]]; then
  python3 - "$BASE" "$name" <<'PY'
import fcntl,json,pathlib,sys,os,tempfile
base=pathlib.Path(sys.argv[1]);p=base/'argo-state.json'
with open(base/'argo-state.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX);s=json.loads(p.read_text());s['node_name']=sys.argv[2]
 with tempfile.NamedTemporaryFile(mode='w',dir=base,delete=False) as f:json.dump(s,f,ensure_ascii=False,indent=2);tmp=f.name
 os.chmod(tmp,0o600);os.replace(tmp,p)
PY
 fi
 exports
}
write_config(){
 # Credentials stay off process arguments; stdin contains the embedded program.
 python3 - 3< <(printf '%s\0' "$@") <<'PY'
import json,os
with os.fdopen(3,'rb') as f:args=f.read().decode('utf-8').split('\0')
if args.pop()!='':raise ValueError('Invalid config input')
conf,meta,domain,cert,key,sni,uuid,priv,pub,sid,password,ip,mode,cert_mode=args[:14]
node_name=args[14] if len(args)>14 else 'SKYBYTE'
vp=int(args[15]) if len(args)>15 else 443;hp=int(args[16]) if len(args)>16 else 443
assert 1<=vp<=65535 and 1<=hp<=65535
listen=args[17] if len(args)>17 and args[17] else ('::' if ':' in ip else '0.0.0.0')
assert listen in ('::','0.0.0.0')
d={'log':{'level':'info','timestamp':True},'inbounds':[{'type':'vless','tag':'reality','listen':listen,'listen_port':443,'users':[{'name':'user1','uuid':uuid,'flow':'xtls-rprx-vision'}],'tls':{'enabled':True,'server_name':sni,'reality':{'enabled':True,'handshake':{'server':sni,'server_port':443},'private_key':priv,'short_id':[sid]}}},{'type':'hysteria2','tag':'hy2','listen':listen,'listen_port':443,'users':[{'name':'user1','password':password}],'tls':{'enabled':True,'server_name':domain,'certificate_path':cert,'key_path':key}}],'outbounds':[{'type':'direct','tag':'direct'}],'route':{'final':'direct'}}
if mode=='1': d['inbounds']=d['inbounds'][:1]
elif mode=='2': d['inbounds']=d['inbounds'][1:]
for i in d['inbounds']:i['listen_port']=vp if i['type']=='vless' else hp
with open(conf,'w') as f:json.dump(d,f,indent=2)
with open(meta,'w') as f:json.dump({'node_name':node_name,'mode':mode,'cert_mode':cert_mode,'cert_path':cert,'managed_certificates':[cert,key] if cert_mode=='1' else [],'ip':ip,'listen':listen,'domain':domain,'sni':sni,'uuid':uuid,'public_key':pub,'sid':sid,'hy2_password':password,'hop':False,'hop_start':20000,'hop_end':30000},f,indent=2)
PY
}
