bbr(){ need_root; confirm "$(L '更改系统 TCP 拥塞控制为 BBR、默认队列为 FQ？' 'Change system TCP congestion control to BBR and default qdisc to FQ?')" || return 0; modprobe tcp_bbr 2>/dev/null || :; if ! sysctl -n net.ipv4.tcp_available_congestion_control | grep -qw bbr; then err "$(L '内核不支持 BBR' 'Kernel does not support BBR')"; return 1; fi
 printf 'net.core.default_qdisc = fq\nnet.ipv4.tcp_congestion_control = bbr\n' >"$SYSCTL_FILE"
 sysctl -p "$SYSCTL_FILE"; sysctl net.ipv4.tcp_congestion_control net.core.default_qdisc; }

hop_guard(){
 local unit=$SYSTEMD_DIR/singbox-v2-hop.service file
 for file in hop.nft hop-iptables.sh; do [[ ! -L $BASE/$file ]] || return 1; done
 if [[ -e $unit || -L $unit ]]; then
  if [[ -L $unit ]] || ! grep -Fxq 'Description=singbox V2 HY2 IPv4 port hopping' "$unit"; then err "$(L '端口跳跃服务归属异常' 'Hopping service ownership mismatch')"; return 1; fi
  if grep -Fxq "ExecStart=/usr/sbin/nft -f $BASE/hop.nft" "$unit"; then :
  elif grep -Fxq "ExecStart=/bin/bash $BASE/hop-iptables.sh start" "$unit" && grep -Fxq "ExecStop=/bin/bash $BASE/hop-iptables.sh stop" "$unit" && [[ -f $BASE/hop-iptables.sh ]] && grep -Fxq '# SKYBYTE managed HY2 hopping' "$BASE/hop-iptables.sh"; then :
  else err "$(L '端口跳跃启动路径异常，拒绝操作' 'Hopping executable mismatch; refusing operation')"; return 1; fi
 fi
}
hop_disable(){
 hop_guard || return 1
 local unit=$SYSTEMD_DIR/singbox-v2-hop.service
 if [[ -f $unit ]]; then
  systemctl disable --now singbox-v2-hop.service || return 1
  if grep -Fxq "ExecStart=/usr/sbin/nft -f $BASE/hop.nft" "$unit"; then nft delete table ip singbox_v2_hop 2>/dev/null || :; fi
 fi
 if [[ -f $META ]]; then python3 - "$META" <<'PY_HOP_OFF'
import json,sys
p=sys.argv[1];d=json.load(open(p));d['hop']=False
with open(p,'w') as f:json.dump(d,f,indent=2)
PY_HOP_OFF
 fi
 say '已关闭托管的端口跳跃；UFW/云防火墙规则请按需要清理。' 'Managed hopping disabled; clean up UFW/provider rules as needed.'
}
hop(){
 check_owned && hop_guard || return 1
 [[ $(protocol_mode) != 1 ]] || { err "$(L '未安装 HY2' 'HY2 not installed')"; return 1; }
 local choice backend start end target
 # --menu renders only; a numeric argument executes one selected operation.
 if [[ $# == 0 || $1 == --menu ]]; then
 say '端口跳跃仅支持 IPv4；规则随 systemd 开机恢复，需要放行云防火墙 UDP 范围。' 'Hopping is IPv4-only, persisted with systemd; allow the provider UDP range.'
 prompt_options '1. 开启
2. 关闭
0. 返回' '1. Enable
2. Disable
0. Back'
 [[ ${1:-} != --menu ]] || return 0
 prompt_read '> ' choice || return 0
 else
  choice=$1
 fi
 if [[ $choice == 2 ]]; then confirm "$(L '关闭跳跃？' 'Disable hopping?')" && hop_disable; return; fi
 [[ $choice == 1 ]] || return 0
 prompt_options '1. nftables（默认）
2. iptables' '1. nftables (default)
2. iptables'
 prompt_read '> ' backend || return 0; backend=${backend:-1}
 case $backend in 1) backend=nftables;; 2) backend=iptables;; *) return 1;; esac
 prompt_read "$(L '起始端口 [20000]：' 'Start port [20000]: ')" start || return 0; start=${start:-20000}
 prompt_read "$(L '结束端口 [40000]：' 'End port [40000]: ')" end || return 0; end=${end:-40000}
 if ! valid_port "$start" || ! valid_port "$end" || ! ((10#$start>=1024 && 10#$start<=10#$end && 10#$end-10#$start<=20000)); then err "$(L '范围非法，最多20001个端口' 'Invalid range, maximum 20001 ports')"; return 1; fi
 start=$((10#$start));end=$((10#$end));target=$(protocol_port hysteria2) || return 1
 if [[ -f $BASE/users.json ]]; then users_guard && users_engine hop_check "$start" "$end" || return 1; fi
 confirm "$(L "将 UDP $start-$end 转发到 HY2 监听端口 ${target}？" "Forward UDP $start-$end to HY2 listener $target?")" || return 0
 if [[ $backend == nftables ]]; then require_cmd nft || return 1; else command -v iptables >/dev/null || { apt_install iptables || return 1; }; fi
 if command -v nft >/dev/null && nft list table ip singbox_v2_hop >/dev/null 2>&1; then err "$(L '已有跳跃规则，请先关闭' 'Hopping rules exist; disable first')"; return 1; fi
 if command -v iptables >/dev/null && iptables -w 5 -t nat -S SKYBYTE_HY2_HOP >/dev/null 2>&1; then err "$(L '已有跳跃链，请先关闭，拒绝覆盖' 'Hopping chain exists; disable first; refusing overwrite')"; return 1; fi
 if [[ $backend == nftables ]]; then
 cat >"$BASE/hop.nft" <<RULES
add table ip singbox_v2_hop
add chain ip singbox_v2_hop prerouting { type nat hook prerouting priority dstnat; policy accept; }
add rule ip singbox_v2_hop prerouting udp dport $start-$end redirect to :$target
RULES
 cat >"$SYSTEMD_DIR/singbox-v2-hop.service" <<UNIT
[Unit]
Description=singbox V2 HY2 IPv4 port hopping
After=network-online.target
[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/sbin/nft -f $BASE/hop.nft
ExecStop=/usr/sbin/nft delete table ip singbox_v2_hop
[Install]
WantedBy=multi-user.target
UNIT
 else
 cat >"$BASE/hop-iptables.sh" <<SCRIPT
#!/usr/bin/env bash
# SKYBYTE managed HY2 hopping
set -Eeuo pipefail
case \${1:-} in
 start)
  iptables -w 5 -t nat -N SKYBYTE_HY2_HOP
  if ! iptables -w 5 -t nat -A SKYBYTE_HY2_HOP -p udp -j REDIRECT --to-ports $target || ! iptables -w 5 -t nat -A PREROUTING -p udp --dport $start:$end -j SKYBYTE_HY2_HOP; then
   iptables -w 5 -t nat -F SKYBYTE_HY2_HOP; iptables -w 5 -t nat -X SKYBYTE_HY2_HOP; exit 1
  fi;;
 stop)
  iptables -w 5 -t nat -D PREROUTING -p udp --dport $start:$end -j SKYBYTE_HY2_HOP || :
  iptables -w 5 -t nat -F SKYBYTE_HY2_HOP || :
  iptables -w 5 -t nat -X SKYBYTE_HY2_HOP || :;;
 *) exit 1;;
esac
SCRIPT
 chmod 700 "$BASE/hop-iptables.sh"
 cat >"$SYSTEMD_DIR/singbox-v2-hop.service" <<UNIT
[Unit]
Description=singbox V2 HY2 IPv4 port hopping
After=network-online.target
[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash $BASE/hop-iptables.sh start
ExecStop=/bin/bash $BASE/hop-iptables.sh stop
[Install]
WantedBy=multi-user.target
UNIT
 fi
 if ! systemctl daemon-reload || ! systemctl enable --now singbox-v2-hop.service; then
  systemctl stop singbox-v2-hop.service || :; err "$(L '跳跃规则启用失败' 'Hopping enable failed')"; return 1
 fi
 python3 - "$META" "$start" "$end" "$backend" "$target" <<'PY_HOP_ON'
import json,sys
p=sys.argv[1];d=json.load(open(p));d.update(hop=True,hop_start=int(sys.argv[2]),hop_end=int(sys.argv[3]),hop_backend=sys.argv[4],hop_target=int(sys.argv[5]))
with open(p,'w') as f:json.dump(d,f,indent=2)
PY_HOP_ON
 if command -v ufw >/dev/null && LC_ALL=C ufw status | grep -q '^Status: active'; then ufw allow "$start:$end/udp" || return 1; fi
 exports
 say '客户端 JSON/YAML 已加入跳跃范围；小火箭请在客户端配置跳跃范围。云安全组也必须放行此范围。' 'JSON/YAML includes hopping ranges; configure hopping manually in Shadowrocket. Allow the provider UDP range too.'
}

latest(){ curl -q -fsSL --connect-timeout 10 --proto '=https' --proto-redir '=https' --max-time 25 https://api.github.com/repos/SagerNet/sing-box/releases/latest | python3 -c 'import json,sys; d=json.load(sys.stdin); assert not d.get("prerelease") and not d.get("draft"); print(d["tag_name"].lstrip("v"))'; }
update(){
 check_owned || return 1
 local new current
 current=$("$BIN" version | awk 'NR==1{print $3}'); new=$(latest) || return 1
 printf '%s -> %s\n' "$current" "$new"
 [[ $current != "$new" ]] || return 0
 confirm "$(L '更新会短暂中断连接，继续？' 'Update briefly interrupts connections. Continue?')" || return 0
 apply_update "$new"
}
managed_restart(){
 local argo_active=false tunnel_active=false users_active=false
 if [[ -f $BASE/warp-gateway.json ]] && systemctl is-active --quiet skybyte-warp-gateway.service; then systemctl restart skybyte-warp-gateway.service && systemctl is-active --quiet skybyte-warp-gateway.service || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-argo-node.service ]] && systemctl is-active --quiet skybyte-argo-node.service; then argo_active=true; fi
 if [[ -f $SYSTEMD_DIR/skybyte-argo-tunnel.service ]] && systemctl is-active --quiet skybyte-argo-tunnel.service; then tunnel_active=true; fi
 if [[ -f $BASE/users.json ]] && systemctl is-active --quiet skybyte-users.service; then users_guard || return 1; users_active=true; fi
 admin_restart || return 1
 if [[ $argo_active == true ]]; then
  systemctl restart skybyte-argo-node.service && systemctl is-active --quiet skybyte-argo-node.service || return 1
  if [[ $tunnel_active == true ]]; then systemctl restart skybyte-argo-tunnel.service || return 1; fi
 fi
 if [[ $users_active == true ]]; then systemctl restart skybyte-users.service || return 1; fi
}
apply_update(){
 local new=$1 snap candidate
 candidate=$(mktemp "$BASE/sing-box.candidate.XXXXXX") || return 1
 snap=$(backup) || { rm -f "$candidate"; return 1; }
 download_binary "$new" "$candidate" || { rm -f "$candidate"; return 1; }
 if [[ -f $BASE/warp-gateway.json ]]; then "$candidate" check -c "$BASE/warp-gateway.json" || { rm -f "$candidate"; return 1; }; fi
 "$candidate" check -c "$CONF" || { rm -f "$candidate"; return 1; }
 if [[ -f $BASE/argo-server.json ]]; then "$candidate" check -c "$BASE/argo-server.json" || { rm -f "$candidate"; return 1; }; fi
 if [[ -f $BASE/users.json ]]; then if ! users_guard || ! users_engine validate "$candidate"; then rm -f "$candidate"; return 1; fi; fi
 command install -m 755 "$candidate" "$BIN" || return 1; rm -f "$candidate"
 if ! managed_restart; then
  command install -m 755 "$snap/sing-box.bin" "$BIN"; warp_restore_snapshot "$snap" || :; admin_restart || :; argo_restore_snapshot "$snap" || :; users_restore_snapshot "$snap" || :
  err "$(L '更新失败，已恢复原二进制' 'Update failed; original binary restored')"; return 1
 fi
 python3 - "$BASE/core-version.json" "$new" "$CORE_RECOMMENDED" <<'PY_CORE_VERSION'
import json,os,pathlib,sys,tempfile,time
p=pathlib.Path(sys.argv[1]);assert not p.is_symlink()
fd,tmp=tempfile.mkstemp(dir=p.parent)
with os.fdopen(fd,'w') as f:json.dump({'owner':'SKYBYTE core version v1','version':sys.argv[2],'tested':sys.argv[3],'updated_at':int(time.time())},f)
os.replace(tmp,p)
PY_CORE_VERSION
 ok "$(L '更新完成，请检查客户端连接' 'Updated; verify client connectivity')"
}
service_healthy(){ sleep 2; systemctl is-active --quiet sing-box; }
retire_auto_update(){
 local unit timer saved
 unit=$SYSTEMD_DIR/singbox-v2-update.service;timer=$SYSTEMD_DIR/singbox-v2-update.timer
 [[ -e $unit || -e $timer || -L $unit || -L $timer ]] || return 0
 if [[ -L $unit || -L $timer ]] || { [[ -f $unit ]] && { ! grep -Fxq 'Description=sing-box v2 weekly update' "$unit" || ! grep -Fxq "ExecStart=/bin/bash $MANAGER_BIN --auto-update" "$unit"; }; } || { [[ -f $timer ]] && ! grep -Fxq 'Description=sing-box v2 weekly update timer' "$timer"; }; then
  warn "$(L '旧更新服务归属异常，保留不修改' 'Legacy update unit ownership mismatch; retained')"; return 0
 fi
 mkdir -p "$BASE/manager-backups"
 saved=$(mktemp -d "$BASE/manager-backups/legacy-auto.XXXXXX") || return 1
 [[ ! -f $unit ]] || cp "$unit" "$saved/" || return 1
 [[ ! -f $timer ]] || cp "$timer" "$saved/" || return 1
 [[ ! -f $timer ]] || systemctl disable --now singbox-v2-update.timer || return 1
 [[ ! -f $unit ]] || systemctl stop singbox-v2-update.service || return 1
 rm -f "$unit" "$timer";systemctl daemon-reload || return 1
 say "已停用旧每周更新，服务文件备份：$saved" "Legacy weekly updater retired; unit backups: $saved"
}
update_auto(){ warn "$(L '每周自动更新已移除，请使用手动更新' 'Weekly updates removed; use manual updates')"; }
ipcheck(){ notice; confirm "$(L '访问 ipinfo.io 检查 IP 并保存本地报告？' 'Query ipinfo.io and save the IP report locally?')" || return 0; local stamp path; stamp=$(date +%Y%m%d-%H%M%S); path="$REPORT/ip-$stamp.json"; curl -4fsSL --max-time 20 https://ipinfo.io/json >"$path" || { rm -f "$path"; err "$(L 'IP 检测失败' 'IP lookup failed')"; return 1; }; chmod 600 "$path"; python3 -m json.tool "$path"; find "$REPORT" -type f -mtime +30 -delete; say "报告：${path}；不是风险或解锁报告" "Report: $path; not a reputation/unblocking test"; }
netcheck(){ local stamp path; stamp=$(date +%Y%m%d-%H%M%S); path="$REPORT/net-$stamp.txt"; { echo "date=$(date -Is)"; echo 'route:'; ip route get 1.1.1.1; echo 'DNS:'; getent ahostsv4 github.com | sed -n '1,3p'; echo 'HTTP:'; curl -4 -o /dev/null -sS --max-time 15 -w 'github_https_code=%{http_code} connect=%{time_connect}s total=%{time_total}s\n' https://github.com || :; echo 'TCP listeners:'; ss -lnt '( sport = :443 )'; echo 'UDP listeners:'; ss -lnu '( sport = :443 )'; } | tee "$path"; chmod 600 "$path"; find "$REPORT" -type f -mtime +30 -delete; say '仅为基础连通性，不测三网回程、UDP 丢包或吞吐量' 'Basic connectivity only; no route-back, UDP loss or throughput testing'; }
protocol_port(){
 python3 - "$CONF" "$1" <<'PY'
import json,sys
port=next(i['listen_port'] for i in json.load(open(sys.argv[1]))['inbounds'] if i['type']==sys.argv[2])
assert isinstance(port,int) and 1<=port<=65535
print(port)
PY
}
hy2_diagnostics(){
 check_owned || return 1
 local port details cert key name listener
 port=$(protocol_port hysteria2) || { err "$(L '未找到 HY2 入站' 'No HY2 inbound found')"; return 1; }
 say '---------------- HY2 连接诊断 ----------------' '---------------- HY2 connection checks ----------------'
 if "$BIN" check -c "$CONF"; then ok "$(L '服务端配置检查通过' 'Server configuration check passed')"; else err "$(L '服务端配置无效' 'Server configuration invalid')"; fi
 if systemctl is-active --quiet sing-box; then ok "$(L 'sing-box 服务正在运行' 'sing-box service is active')"; else err "$(L 'sing-box 服务未运行；请查看服务与日志 → 日志（c → 2） 日志' 'sing-box is not active; inspect Services and logs > Logs (c > 2) logs')"; fi
 listener=$(ss -H -lun "( sport = :$port )") || return 1
 if [[ -n $listener ]]; then ok "$(L "本机 UDP $port 有监听" "Local UDP $port has a listener")"; else err "$(L "本机 UDP $port 未监听" "No local UDP $port listener")"; fi
 details=$(python3 - "$CONF" <<'PY'
import json,sys
c=next(i for i in json.load(open(sys.argv[1]))['inbounds'] if i['type']=='hysteria2')['tls']
for field in ['certificate_path','key_path','server_name']:print(c[field])
PY
 ) || return 1
 { read -r cert; read -r key; read -r name; } <<<"$details"
 if validate_certificate "$cert" "$key" "$name"; then ok "$(L '证书有效期、名称与私钥匹配检查通过' 'Certificate expiry, name and key matching checks passed')"; else err "$(L '证书检查失败，请检查文件或证书身份' 'Certificate checks failed; inspect files and certificate identity')"; fi
 openssl x509 -in "$cert" -noout -dates -fingerprint -sha256 || return 1
 firewall_audit
 warn "$(L '本机检查不能证明手机到 VPS 的 UDP 可达，也不能证明小火箭已信任证书。' 'Local checks do not prove phone-to-VPS UDP reachability or Shadowrocket certificate trust.')"
 say 'certificate/x509 错误：检查客户端证书信任、SNI 和指纹。' 'certificate/x509 errors: check client certificate trust, SNI and fingerprint.'
 say 'timeout/no recent network activity：检查本机与云防火墙 UDP，换 Wi-Fi/移动网络测试。' 'timeout/no recent network activity: inspect local/provider UDP rules and try another Wi-Fi/mobile network.'
 say 'authentication failed：重新导出、导入节点，核对密码；不要公开节点链接。' 'authentication failed: re-export/import the node and verify password; do not publish the URI.'
 say '请用小火箭实际连接或 URL 测试；普通 ICMP 延迟不能验证 HY2。' 'Use an actual Shadowrocket connection or URL test; ICMP latency does not validate HY2.'
 printf '%s\n' "$(L '只读抓包命令（连接节点时执行；不显示数据包内容）：' 'Read-only packet check while connecting (does not display packet contents):')"
 printf '  sudo timeout 15 tcpdump -nn -i any "udp port %s"\n' "$port"
 say '---------------- 诊断结束 ----------------' '---------------- End of checks ----------------'
}
firewall_audit(){
 if command -v ufw >/dev/null; then
  local rules hy2_port; rules=$(LC_ALL=C ufw status); printf '%s\n' "$rules"
  if [[ -f $META && $(protocol_mode) != 1 && $rules == *'Status: active'* ]]; then
   hy2_port=$(protocol_port hysteria2) || return 1
   grep -Eq "${hy2_port}/udp[[:space:]]+ALLOW" <<<"$rules" || warn "$(L "未检测到 UDP $hy2_port 放行，请检查规则" "UDP $hy2_port allow rule not detected; inspect rules")"
   if [[ $(state hop) == True ]]; then
    grep -F "$(state hop_start):$(state hop_end)/udp" <<<"$rules" | grep -q ALLOW || warn "$(L '未检测到跳跃 UDP 范围放行' 'Hopping UDP range allow rule not detected')"
   fi
  fi
 else warn "$(L '未安装 UFW；请检查 nftables 和云防火墙' 'UFW unavailable; inspect nftables and provider firewall')"; fi
 warn "$(L '云防火墙须在服务商控制台检查' 'Check provider firewall in the hosting console')"
}
status(){
 systemctl --no-pager status sing-box 2>&1 | head -25 || :
 local protocol port
 if [[ -f $CONF ]];then
  for protocol in vless hysteria2;do
   if port=$(protocol_port "$protocol" 2>/dev/null);then
    printf '%s: %s\n' "$protocol" "$port"
    if [[ $protocol == vless ]];then ss -ltn "( sport = :$port )";else ss -lun "( sport = :$port )";fi
   fi
  done
 fi
 echo 'UFW:';firewall_audit;echo 'Hop:'
 if [[ -f $META && $(state hop_backend) == iptables ]];then iptables -w 5 -t nat -S SKYBYTE_HY2_HOP 2>/dev/null || :;else nft list table ip singbox_v2_hop 2>/dev/null || :;fi
}
restore() (
 check_owned || return 1
 local path snap='' restore_stage='' restore_started=false restore_done=false service active enabled
 trap restore_cleanup EXIT
 find "$BACKUP" -mindepth 1 -maxdepth 1 -type d | sort -r
 prompt_read "$(L '完整备份路径：' 'Full backup directory path: ')" path || return
 path=$(realpath "$path") || return 1
 [[ $path == "$(realpath "$BACKUP")/"* && -f $path/config/config.json && -f $path/sing-box.bin && -f $path/state.json ]] || { err "$(L '备份路径错误' 'Invalid backup path')"; return 1; }
 confirm "$(L '恢复配置并重启？' 'Restore configuration and restart?')" || return 0
 configuration_guard && argo_guard && hop_guard || return 1
 users_guard || return 1
 backup_engine preflight "$path" || return 1
 haproxy_engine check_configs "$path" || return 1
 snap=$(backup) || return 1
 restore_stage=$(mktemp -d "$BASE/restore.XXXXXX") || return 1
 backup_engine restore_plan "$path" "$restore_stage" || return 1
 for service in skybyte-warp-gateway.service sing-box.service skybyte-argo-node.service skybyte-argo-tunnel.service skybyte-users.service singbox-v2-hop.service;do
  [[ -f $SYSTEMD_DIR/$service ]] || continue
  active=false;enabled=false
  if systemctl is-active --quiet "$service";then active=true;fi
  if systemctl is-enabled --quiet "$service";then enabled=true;fi
  printf '%s %s %s\n' "$service" "$active" "$enabled" >> "$restore_stage/services"
 done
 restore_started=true
 users_stop || return 1
 backup_engine restore_apply "$restore_stage" || return 1
 "$BIN" check -c "$CONF" && warp_restore_snapshot "$path" && admin_restart && argo_restore_snapshot "$path" && users_restore_snapshot "$path" || return 1
 # Hopping is host state: avoid restoring metadata claiming rules that are absent.
 hop_disable || return 1
 exports >/dev/null || return 1
 if [[ -f $BASE/users.json ]];then users_engine export_all | while IFS= read -r service;do users_export "$service" >/dev/null || return 1;done || return 1;fi
 auxiliary_restore_snapshot "$path" || return 1
 restore_done=true
 ok "$(L '配置已恢复；需要跳跃时请重新开启' 'Configuration restored; re-enable hopping if needed')"
)
restore_cleanup(){
 local rc=$? failed=false service active enabled
 if [[ ${restore_started:-false} == true && ${restore_done:-false} != true ]];then
  users_stop || failed=true
  backup_engine restore_rollback "$restore_stage" || failed=true
  warp_restore_snapshot "$snap" || failed=true
  argo_restore_snapshot "$snap" || failed=true
  users_restore_snapshot "$snap" || failed=true
  if [[ -f $restore_stage/services ]];then
   while read -r service active enabled;do
    if [[ $enabled == true ]];then systemctl enable "$service" || failed=true;else systemctl disable "$service" || failed=true;fi
    if [[ $active == true ]];then systemctl restart "$service" || failed=true;else systemctl stop "$service" || failed=true;fi
   done < "$restore_stage/services"
  fi
  exports >/dev/null || failed=true
  if [[ -f $BASE/users.json ]];then users_engine export_all | while IFS= read -r service;do users_export "$service" >/dev/null || return 1;done || failed=true;fi
  if [[ $failed == true ]];then err "$(L "恢复失败，回滚未全部完成；保留事务：$restore_stage；备份：$snap" "Restore failed; rollback incomplete. Transaction retained: $restore_stage; backup: $snap")"
  else err "$(L '恢复失败，已恢复原文件和服务状态' 'Restore failed; original files and service states restored')";fi
 fi
 if [[ -n ${restore_stage:-} && $failed == false ]];then rm -rf -- "$restore_stage";fi
 return "$rc"
}
# Optional fresh-server preparation. No SSH, firewall, kernel or reboot changes.
initialize_server(){
 need_root
 if [[ ! -r $OS_RELEASE ]]; then err "$(L '无法识别操作系统' 'Cannot detect operating system')"; return 1; fi
 # shellcheck source=/dev/null
 . "$OS_RELEASE"
 case "${ID:-}" in
  ubuntu|debian) ;;
  *) err "$(L "只支持 Ubuntu/Debian，当前：${ID:-unknown}" "Ubuntu/Debian only; detected ${ID:-unknown}")"; return 1;;
 esac
 command -v apt-get >/dev/null || { err "$(L '缺少 apt-get' 'apt-get not found')"; return 1; }
 say "系统：${PRETTY_NAME:-$ID}" "System: ${PRETTY_NAME:-$ID}"
 say '本功能将更新 apt 索引、升级已安装软件、安装诊断工具。' 'This updates apt indexes, upgrades installed packages, and installs diagnostic tools.'
 say '不会自动启用 UFW、变更 SSH、修改 BBR 或重启系统。' 'Does not enable UFW, change SSH/BBR, or reboot.'
 warn "$(L '升级可能更改内核、SSH 等软件包；建议先做 VPS 快照并保留控制台。' 'Updates may change kernel/SSH; create a snapshot and retain console access.')"
 confirm "$(L '确认执行新服务器初始化？' 'Initialize this server (including system upgrade)?')" || { say '已取消' Cancelled; return 0; }
 local -a packages=(curl wget nano vim unzip zip tar openssl ca-certificates ufw iproute2 iputils-ping dnsutils traceroute mtr-tiny net-tools netcat-openbsd jq git socat lsof htop python3 bc util-linux nftables procps)
 # Installing chrony can remove timesyncd; keep an existing active time-sync service.
 if ! systemctl is-active --quiet chrony && ! systemctl is-active --quiet systemd-timesyncd && ! systemctl is-active --quiet ntp && ! systemctl is-active --quiet ntpsec; then packages+=(chrony); fi
 say '更新软件索引...' 'Updating package indexes...'
 apt_refresh || { err "$(L '软件索引更新失败' 'Package index update failed')"; return 1; }
 say '升级已安装软件（不会自动执行 full-upgrade）...' 'Upgrading packages (not full-upgrade)...'
 DEBIAN_FRONTEND=noninteractive apt-get upgrade -y || { err "$(L '系统升级失败；请检查 apt/dpkg 状态' 'Upgrade failed; check apt/dpkg status')"; return 1; }
 say '安装基础工具...' 'Installing essential tools...'
 apt_install "${packages[@]}" || { err "$(L '工具安装失败' 'Tool installation failed')"; return 1; }
 say '检测时间同步服务...' 'Checking time synchronization...'
 if command -v timedatectl >/dev/null 2>&1; then timedatectl status --no-pager 2>/dev/null || :; fi
 # Do not forcibly disable an existing time-sync daemon.
 if systemctl is-active --quiet chrony 2>/dev/null; then
  say 'chrony 已运行。' 'chrony is running.'
 elif systemctl is-active --quiet systemd-timesyncd 2>/dev/null || systemctl is-active --quiet ntp 2>/dev/null || systemctl is-active --quiet ntpsec 2>/dev/null; then
  say '其他时间同步服务正在运行，不会强制切换到 chrony。' 'Another time synchronization service is running; not switching.'
 else
  say '尝试启用 chrony 时间同步...' 'Trying to enable chrony...'
  systemctl enable --now chrony 2>/dev/null || warn "$(L 'chrony 未启动，请人工检查' 'chrony did not start; check manually')"
 fi
 say '========== 只读检查 ==========' '========== Read-only checks =========='
 echo 'DNS github.com:'
 getent ahostsv4 github.com | sed -n '1,3p' || say 'DNS 解析失败' 'DNS resolution failed'
 say 'GitHub HTTPS:' 'GitHub HTTPS:'
 curl -4sS -I -L --connect-timeout 8 --max-time 18 -o /dev/null -w 'HTTP %{http_code}\n' https://github.com || warn "$(L 'HTTPS 无法连接' 'HTTPS connection failed')"
 say 'SSH 监听端口（仅查看）：' 'SSH listening ports (read-only):'
 ss -ltnp | grep -E 'sshd|:22[[:space:]]' || say '未识别 sshd 监听，请自行核实实际 SSH 端口' 'Could not identify sshd; verify actual SSH port'
 say 'UFW 状态（没有自动开启）：' 'UFW status (not enabled automatically):'
 ufw status verbose || :
 say '系统内核：' Kernel:
 uname -r
 say '如内核或关键服务已升级，请在维护窗口确认后自行决定是否重启。' 'If kernel or essential services were upgraded, plan a manual reboot if necessary.'
 say '新服务器初始化结束。' 'Server initialization complete.'
}

# UFW safety: never assume SSH port 22, and never bypass cloud firewall checks.
detect_ssh_ports(){
 local ports connection_port
 connection_port=$(awk '{print $4}' <<<"${SSH_CONNECTION:-}")
 ports=$(ss -H -lntp | awk '/sshd/ {n=split($4,a,":"); print a[n]}' | sort -nu)
 if [[ -z $ports ]] && command -v sshd >/dev/null; then ports=$(sshd -T 2>/dev/null | awk '$1=="port"{print $2}' | sort -nu); fi
 if valid_port "$connection_port"; then ports=$(printf '%s\n%s\n' "$ports" "$connection_port" | sed '/^$/d' | sort -nu); fi
 SSH_PORTS=$ports
 printf '%s\n' "$(L '识别到 SSH 端口（请确认）：' 'Detected SSH ports (verify): ')$ports"
}
firewall(){
 local choice port proto
 need_root
 # --menu renders only; a numeric argument executes one selected operation.
 if [[ $# == 0 || $1 == --menu ]]; then
 prompt_options '========== UFW 防火墙 ==========
1. 安装 UFW
2. 开启防火墙
3. 关闭防火墙
4. 查看状态
5. 放行端口
6. 删除规则
0. 返回上一层' '========== UFW firewall ==========
1. Install UFW
2. Enable firewall
3. Disable firewall
4. Show status
5. Allow a port
6. Delete a rule
0. Back one level'
 [[ ${1:-} != --menu ]] || return 0
 prompt_read '> ' choice || return
 else
  choice=$1
 fi
 case "$choice" in
 1) confirm "$(L '安装 UFW？' 'Install UFW?')" && apt_install ufw ;;
 2)
   require_cmd ufw || return
   say '当前 SSH 监听信息（必须人工核实）：' 'SSH listener information (VERIFY manually):'
   detect_ssh_ports
   prompt_read "$(L '输入当前 SSH TCP 端口（请核实云控制台/sshd 设置）：' 'Enter verified SSH TCP port: ')" port
   port=${port:-${SSH_PORTS:-}}
   valid_port "$port" || { err "$(L 'SSH 端口无效' 'Invalid SSH port')"; return 1; }
   warn "$(L '如果 SSH 端口判断错误，开启 UFW 可能导致远程连接断开！请保留 VPS 控制台访问。' 'Wrong SSH port may lock you out. Keep VPS console access.')"
   say '将放行 SSH 与实际节点、订阅和 HTTP证书验证端口。' 'Will allow SSH and actual node, subscription and HTTP certificate-validation ports.'
   confirm "$(L '确认开启 UFW 防火墙？' 'Enable UFW now?')" || return 0
   ufw allow "$port/tcp" || return 1
   local detected
   while read -r detected; do [[ -z $detected ]] || ufw allow "$detected/tcp" || return 1; done <<<"$SSH_PORTS"
   firewall_allow_protocols || return 1
   if [[ -f $META && $(state hop) == True ]]; then ufw allow "$(state hop_start):$(state hop_end)/udp" || return 1; fi
   ufw default deny incoming; ufw default allow outgoing; ufw --force enable
   warn "$(L '如有 HY2 跳跃或云防火墙，需另外确认规则。' 'Check HY2 hopping and provider firewall rules separately.')" ;;
 3) require_cmd ufw && confirm "$(L '关闭 UFW 会降低保护，确定？' 'Disable UFW and reduce protection?')" && ufw --force disable ;;
 4) require_cmd ufw && ufw status verbose ;;
 5) require_cmd ufw || return
    prompt_read "$(L '端口：' 'Port: ')" port; valid_port "$port" || return 1
    prompt_read "$(L '协议 (tcp/udp)：' 'Protocol (tcp/udp): ')" proto; [[ $proto == tcp || $proto == udp ]] || return 1
    confirm "$(L "放行 $port/${proto}？" "Allow $port/$proto?")" && ufw allow "$port/$proto" ;;
 6) require_cmd ufw || return; ufw status numbered
    prompt_read "$(L '规则编号：' 'Rule number: ')" port; [[ $port =~ ^[0-9]+$ ]] || return 1
    confirm "$(L '删除指定规则？确认不会影响 SSH！' 'Delete rule? Ensure SSH stays reachable!')" && ufw --force delete "$port" ;;
 0) return;; *) err "$(L '无效选择' 'Invalid choice')";;
 esac
 return 0
}
