   elif action=='validity':u['expires_at']=int(time.time())+days(args[1])
   atomic(db,d)
   if action in ('set','quota','validity'):print(tr('修改后到期时间：','Resulting expiry: ')+expiry(u))
 elif action=='list':
  color=sys.stdout.isatty() and not os.environ.get('NO_COLOR')
