4. 关闭每日检查
0. 返回' '1. Expiry
2. Reload renewed certificate
3. Enable daily checks
4. Disable daily checks
0. Back'
 [[ ${1:-} != --menu ]] || return 0
 prompt_read '> ' choice || return 0
 else
  choice=$1
 fi
 case $choice in
  1) certificate_info;;
  2) confirm "$(L '同步证书并重启正在运行的 HY2 服务？' 'Sync certificates and restart active HY2 services?')" && certificate_reload;;
  3)
   users_guard setup || return 1
