install_check_engine(){ python3 - "$@" <<'PY_INSTALL_CHECKS'
"""Bounded installation diagnostics: no package, firewall or configuration changes."""
import argparse
import errno
import fcntl
import json
import os
from pathlib import Path
import platform
import queue
import shutil
import socket
import ssl
import stat
import subprocess
import sys
import threading
import urllib.error
import urllib.request


class Report:
    def __init__(self, english=False):
        self.english = english
        self.items = []

    def tr(self, zh, en):
        return en if self.english else zh

    def add(self, status, zh, en, detail_zh, detail_en=None):
        self.items.append((status, self.tr(zh, en),
                           self.tr(detail_zh, detail_en if detail_en is not None else detail_zh)))

    def render(self):
        def clean(value):
            return json.dumps(str(value), ensure_ascii=False)[1:-1]
        print(self.tr('\n========== 节点安装前检测 ==========', '\n========== NODE INSTALLATION CHECK =========='))
        for status, label, detail in self.items:
            title = {'pass': self.tr('通过', 'PASS'), 'warn': self.tr('提醒', 'WARN'), 'fail': self.tr('失败', 'FAIL')}[status]
            print('[' + title + '] ' + clean(label) + ': ' + clean(detail))
        failed = any(item[0] == 'fail' for item in self.items)
        warnings = sum(item[0] == 'warn' for item in self.items)
        summary = self.tr('检测未通过：请先处理失败项，停止本次安装。', 'FAILED: resolve failed checks before installing.') if failed else self.tr(
            '本阶段检测通过；请核对提醒项。', 'This stage passed; review any warnings.')
        color = ('\033[1;31m' if failed else '\033[1;32m') if sys.stdout.isatty() and not os.environ.get('NO_COLOR') else ''
        print(color + '===== ' + summary + ' =====' + ('\033[0m' if color else ''))
        print(self.tr('提醒数量：', 'Warnings: ') + str(warnings))
        print(self.tr('仅检测本 VPS；端口可绑定不代表公网可达。云安全组、NAT 映射和客户端连接须另行核对。',
                      'Checks this VPS only. A bindable port is not proof of public reachability; inspect provider rules, NAT mappings and client access.'))
        return int(failed)


def package_locks(paths):
    """APT/dpkg use POSIX record locks; an existing unlocked file is normal."""
    busy, unknown = [], []
    for path in map(Path, paths):
        fd = None
        try:
            if path.is_symlink():
                unknown.append(str(path))
                continue
            fd = os.open(path, os.O_RDWR | getattr(os, 'O_NOFOLLOW', 0))
            if not stat.S_ISREG(os.fstat(fd).st_mode):
                unknown.append(str(path))
                continue
            fcntl.lockf(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fcntl.lockf(fd, fcntl.LOCK_UN)
        except FileNotFoundError:
            pass
        except OSError as error:
            if error.errno in (errno.EACCES, errno.EAGAIN) and fd is not None:
                busy.append(str(path))
            else:
                unknown.append(str(path))
        finally:
            if fd is not None:
                os.close(fd)
    return busy, unknown


def environment(report, project, os_release='/etc/os-release', paths=(), reality=False):
    report.add('pass' if os.geteuid() == 0 else 'fail', '运行权限', 'Privileges',
               'root' if os.geteuid() == 0 else '请以 root 账户运行',
               'root' if os.geteuid() == 0 else 'Run as root')
    distro = ''
    try:
        for line in Path(os_release).read_text().splitlines():
            if line.startswith('ID='):
                distro = line.split('=', 1)[1].strip().strip('"\'')
    except OSError:
        pass
    supported = platform.system() == 'Linux' and distro in ('ubuntu', 'debian')
    report.add('pass' if supported else 'fail', '系统支持', 'Operating system',
               'Linux / ' + distro if supported else '需要 Ubuntu/Debian Linux；检测到：' + (distro or platform.system()),
               'Linux / ' + distro if supported else 'Ubuntu/Debian Linux required; detected: ' + (distro or platform.system()))
    architectures = {'x86_64', 'aarch64', 'arm64'}
    if project == 'sing-box':
        architectures |= {'i386', 'i486', 'i586', 'i686', 'armv7l'}
    machine = platform.machine()
    report.add('pass' if machine in architectures else 'fail', '核心架构', 'Core architecture', machine)
    systemd = Path('/run/systemd/system').is_dir()
    report.add('pass' if systemd else 'fail', 'systemd', 'systemd',
               '可用' if systemd else '未发现正在运行的 systemd；无法安装托管服务',
               'Available' if systemd else 'Running systemd not found; managed services cannot be installed')
    if reality:
        report.add('pass' if ssl.HAS_TLSv1_3 else 'fail', 'Python TLS 1.3', 'Python TLS 1.3',
                   '支持握手目标检测' if ssl.HAS_TLSv1_3 else 'Python/OpenSSL 不支持 TLS 1.3，请先升级系统依赖',
                   'Target checks supported' if ssl.HAS_TLSv1_3 else 'Upgrade system Python/OpenSSL for TLS 1.3 target checks')
    busy, unknown = package_locks(['/var/lib/dpkg/lock-frontend', '/var/lib/dpkg/lock',
                                   '/var/lib/apt/lists/lock', '/var/cache/apt/archives/lock'])
    if busy:
        report.add('fail', 'APT/DPKG 锁', 'APT/DPKG locks',
                   '其他软件安装任务正在占用：' + ', '.join(busy) + '；等待任务完成后重试，请勿删除锁文件。',
                   'Another package task holds: ' + ', '.join(busy) + '; wait for it to finish. Do not delete lock files.')
    elif unknown:
        report.add('warn', 'APT/DPKG 锁', 'APT/DPKG locks',
                   '无法确认锁状态，请检查权限或异常路径：' + ', '.join(unknown),
                   'Cannot inspect locks; check permissions or unsafe paths: ' + ', '.join(unknown))
    else:
        report.add('pass', 'APT/DPKG 锁', 'APT/DPKG locks', '当前未被占用', 'Currently available')
    missing = [tool for tool in ('apt-get', 'curl', 'openssl', 'ss', 'ip', 'flock') if not shutil.which(tool)]
    report.add('fail' if 'apt-get' in missing else 'warn' if missing else 'pass', '依赖命令', 'Dependency commands',
               '缺少或不在 PATH：' + ', '.join(missing) + '；请核对 root PATH，安装流程会补齐可安装的依赖。' if missing else '所需命令可用',
               'Missing or outside PATH: ' + ', '.join(missing) + '; inspect root PATH; installation will add available dependencies.' if missing else 'Required commands available')
    seen = set()
    for destination in map(Path, paths):
        current = destination
        while not current.exists() and current != current.parent:
            current = current.parent
        if any(p.is_symlink() for p in (destination, *destination.parents)):
            report.add('fail', '安装路径', 'Installation path', '路径包含符号链接：' + str(destination),
                       'Path contains a symlink: ' + str(destination))
            continue
        try:
            device = current.stat().st_dev
            if device in seen:
                continue
            seen.add(device)
            info = os.statvfs(current)
            free = info.f_bavail * info.f_frsize // (1024 * 1024)
            blocked = bool(info.f_flag & getattr(os, 'ST_RDONLY', 1)) or info.f_favail == 0 or info.f_bavail == 0
            report.add('fail' if blocked else 'warn' if free < 256 else 'pass', '安装存储空间', 'Installation storage',
                       str(current) + '：可用 ' + str(free) + ' MiB' + ('；空间/inode 已耗尽或文件系统只读' if blocked else '；低于 256 MiB，建议先清理' if free < 256 else ''),
                       str(current) + ': ' + str(free) + ' MiB free' + ('; storage/inodes exhausted or filesystem read-only' if blocked else '; below 256 MiB, free space before installing' if free < 256 else ''))
        except OSError:
            report.add('fail', '安装存储空间', 'Installation storage', '无法检查：' + str(destination), 'Cannot inspect: ' + str(destination))


def ports(report, listen, tcp=None, udp=None):
    if tcp is None and udp is None:
        raise ValueError('Port required')
    family = socket.AF_INET6 if ':' in listen else socket.AF_INET
    for protocol, number, kind in (('TCP', tcp, socket.SOCK_STREAM), ('UDP', udp, socket.SOCK_DGRAM)):
        if number is None:
            continue
        if not 1 <= number <= 65535:
            raise ValueError('Invalid port')
        label = protocol + ' ' + str(number)
        try:
            with socket.socket(family, kind) as sock:
                if kind == socket.SOCK_STREAM:
                    # Match server binds: TCP TIME_WAIT is reusable, active listeners are not.
                    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                if family == socket.AF_INET6:
                    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)
                sock.bind((listen, number))
            report.add('pass', label, label, '本机可绑定（' + listen + '）', 'Locally bindable (' + listen + ')')
        except OSError as error:
            occupied = error.errno == errno.EADDRINUSE
            report.add('fail', label, label,
                       '已被占用，请选择其他空闲端口；TCP 与 UDP 分别检查。' if occupied else '无法绑定该地址族/端口，请检查 IPv4/IPv6 与系统权限。',
                       'Occupied; choose another free port. TCP and UDP are checked separately.' if occupied else 'Cannot bind; check IPv4/IPv6 support and privileges.')
    active = []
    for executable, arguments, token in [('ufw', ['status'], 'Status: active'), ('firewall-cmd', ['--state'], 'running')]:
        if not shutil.which(executable):
            continue
        try:
            result = subprocess.run([executable, *arguments], capture_output=True, text=True, timeout=3,
                                    env={**os.environ, 'LC_ALL': 'C'})
            if result.returncode == 0 and token in result.stdout:
                active.append(executable)
        except (OSError, subprocess.SubprocessError):
            pass
    report.add('warn', '防火墙与公网端口', 'Firewall and public ports',
               ('已启用 ' + ', '.join(active) + '；' if active else '未确认已启用 UFW/firewalld，请安装/启用合适的防火墙；') + '先放行 SSH 和实际 TCP/UDP 端口，并核对云安全组；不自动修改规则。',
               ('Active: ' + ', '.join(active) + '. ' if active else 'Active UFW/firewalld not confirmed; install/enable a suitable firewall. ') + 'Allow SSH and actual TCP/UDP ports, and inspect provider rules; rules are not changed.')


def download(report, offline=False, timeout=10, existing_core=False):
    if offline or existing_core:
        report.add('warn', 'GitHub HTTPS', 'GitHub HTTPS',
                   '本机已有核心，本次沿用，跳过不必要的下载联网检测' if existing_core else '离线安装包模式，跳过联网检测',
                   'Existing local core will be reused; unnecessary download/network check skipped' if existing_core else 'Offline asset mode; network check skipped')
        return
    try:
        results = queue.Queue()
        opener = urllib.request.urlopen
        def request_head():
            try:
                request = urllib.request.Request('https://github.com/', method='HEAD', headers={'User-Agent': 'SKYBYTE-Installation-Check'})
                with opener(request, timeout=min(8, timeout), context=ssl.create_default_context()) as response:
                    if not 200 <= response.status < 400:
                        raise urllib.error.HTTPError(request.full_url, response.status, '', {}, None)
                results.put(None)
            except Exception as error:
                results.put(error)
        # Socket timeouts alone do not bound libc DNS resolution.
        threading.Thread(target=request_head, daemon=True).start()
        try:
            error = results.get(timeout=timeout)
        except queue.Empty:
            raise TimeoutError('HTTPS deadline') from None
        if error is not None:
            raise error
        report.add('pass', 'GitHub HTTPS', 'GitHub HTTPS', '首页 HTTPS 与证书验证通过；正式下载仍需校验 API/CDN 与文件摘要',
                   'Homepage HTTPS and certificate verified; downloads still require API/CDN access and digest checks')
    except (OSError, urllib.error.URLError, ValueError) as error:
        reason = getattr(error, 'reason', error)
        if isinstance(reason, ssl.SSLCertVerificationError):
            zh, en = '证书验证失败，请检查 VPS 时间、CA 证书与 HTTPS 拦截', 'Certificate verification failed; check VPS clock, CA roots and HTTPS interception'
        elif isinstance(reason, (TimeoutError, socket.timeout)):
            zh, en = '连接超时，请检查 VPS 出站网络或使用离线安装包', 'Connection timed out; inspect egress connectivity or use offline assets'
        elif isinstance(reason, socket.gaierror):
            zh, en = 'DNS 解析失败，请先修复 VPS DNS', 'DNS lookup failed; repair VPS DNS first'
        elif isinstance(error, urllib.error.HTTPError):
            zh, en = 'HTTP ' + str(error.code) + '，请检查访问限制或限流', 'HTTP ' + str(error.code) + '; check access restrictions or rate limits'
        else:
            zh, en = 'HTTPS 连接失败，请检查出站网络、DNS 与系统时间', 'HTTPS connection failed; inspect egress, DNS and system clock'
        status = 'warn' if isinstance(error, urllib.error.HTTPError) and error.code in (403, 405, 429) else 'fail'
        if status == 'warn':
            zh += '；首页响应不等于发布附件可用性，将由正式下载与摘要校验确认。'
            en += '; homepage status does not establish release-asset availability; verified download will decide.'
        report.add(status, 'GitHub HTTPS', 'GitHub HTTPS', zh, en)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project', choices=('sing-box', 'xray'), required=True)
    parser.add_argument('--phase', choices=('environment', 'ports', 'download'), required=True)
    parser.add_argument('--language', default='zh')
    parser.add_argument('--os-release', default='/etc/os-release')
    parser.add_argument('--paths', nargs='*', default=[])
    parser.add_argument('--reality', action='store_true')
    parser.add_argument('--listen', choices=('0.0.0.0', '::', '127.0.0.1', '::1'), default='0.0.0.0')
    parser.add_argument('--tcp-port', type=int)
    parser.add_argument('--udp-port', type=int)
    parser.add_argument('--offline', action='store_true')
    parser.add_argument('--existing-core', action='store_true')
    options = parser.parse_args(argv)
    report = Report(options.language in ('en', 'en_US'))
    try:
        if options.phase == 'environment':
            environment(report, options.project, options.os_release, options.paths, options.reality)
        elif options.phase == 'ports':
            ports(report, options.listen, options.tcp_port, options.udp_port)
        else:
            print(report.tr('正在检查 GitHub HTTPS（网络等待上限 10 秒）……',
                            'Checking GitHub HTTPS (10-second network wait limit)…'), flush=True)
            download(report, options.offline, existing_core=options.existing_core)
    except (OSError, ValueError, TypeError):
        report.add('fail', '检测参数', 'Check parameters', '参数无效或无法读取本机环境', 'Invalid parameters or unreadable local environment')
    return report.render()


if __name__ == '__main__':
    sys.exit(main())
PY_INSTALL_CHECKS
}
install_environment_check(){
 local options=(--project sing-box --language "${LANGUAGE_CHOICE:-zh_CN}" --phase environment --os-release "$OS_RELEASE")
 [[ ${1:-1} == 2 ]] || options+=(--reality)
 install_check_engine "${options[@]}" --paths "$BASE" "$(dirname "$BIN")" "${TMPDIR:-/tmp}"
}
install_port_check(){
 local mode=$1 tcp=$2 udp=$3 listen=${4:-0.0.0.0} options=()
 [[ $mode == 2 ]] || options+=(--tcp-port "$tcp")
 [[ $mode == 1 ]] || options+=(--udp-port "$udp")
 if ! install_check_engine --project sing-box --language "${LANGUAGE_CHOICE:-zh_CN}" --phase ports --listen "$listen" "${options[@]}";then
  err "$(L '需要其他端口时，可用 a → 6 → 3 自定义监听端口安装；请保留现有服务并选择空闲端口。' 'For another port, use a → 6 → 3 to install with custom ports. Retain existing services and choose a free port.')"
  return 1
 fi
}
install_reality_target(){
 say '正在检查 Reality 目标的 DNS、TCP、TLS 与证书（总时限 12 秒）……' 'Checking Reality target DNS, TCP, TLS and certificate (12-second deadline)…'
 if ! reality_engine --project sing-box --language "${LANGUAGE_CHOICE:-zh_CN}" --target "$1:443" --sni "$1";then
  err "$(L 'Reality 握手目标检测未通过；请更换握手网站或修复 VPS 出站网络、DNS、时间与 CA 证书后重试。尚未写入新节点。' 'Reality target failed checks. Change the target or repair VPS egress, DNS, clock and CA roots before retrying. No new node was written.')"
  return 1
 fi
}
reality_install_check(){
 install_port_check 1 "$2" 443 "${3:-0.0.0.0}" && install_reality_target "$1"
}
install_download_check(){
 local options=(--project sing-box --language "${LANGUAGE_CHOICE:-zh_CN}" --phase download)
 [[ -z ${SKYBYTE_ASSET_DIR:-} ]] || options+=(--offline)
 install_check_engine "${options[@]}"
}
installation_check_menu(){
 local choice tcp=443 udp=443 sni=addons.mozilla.org family listen=0.0.0.0
 if [[ $# == 0 || $1 == --menu ]];then
  prompt_options '节点安装前检测（不安装）
1. Reality + Vision（TCP）
2. Hysteria2（UDP）
3. 双协议（TCP + UDP）
0. 返回' 'Node installation checks (no installation)
1. Reality + Vision (TCP)
2. Hysteria2 (UDP)
3. Both (TCP + UDP)
0. Back'
  [[ ${1:-} != --menu ]] || return 0
  prompt_read '> ' choice || return 0
 else choice=$1;fi
 case $choice in 1|2|3);;0)return 0;;*)return 1;;esac
 if [[ $choice != 2 ]];then prompt_read 'Reality TCP [443]: ' tcp || return 0;tcp=${tcp:-443};fi
 if [[ $choice != 1 ]];then prompt_read 'HY2 UDP [443]: ' udp || return 0;udp=${udp:-443};fi
 valid_port "$tcp" && valid_port "$udp" || return 1
 prompt_options '监听地址族：
1. IPv4（默认）
2. IPv6' 'Listen family:
1. IPv4 (default)
2. IPv6'
 prompt_read '> ' family || return 0
 case ${family:-1} in 1);;2)listen=::;;*)return 1;;esac
 if [[ $choice != 2 ]];then
  prompt_read 'Reality SNI [addons.mozilla.org]: ' sni || return 0;sni=${sni:-addons.mozilla.org}
 fi
 install_environment_check "$choice" && install_port_check "$choice" "$tcp" "$udp" "$listen" || return 1
 [[ $choice == 2 ]] || install_reality_target "$sni" || return 1
 install_download_check
}

warp_engine(){
 python3 - "$BASE" "$CONF" "$BIN" "$@" <<'PY_WARP'
"""Owned WARP/landing routing transactions; client-facing node credentials stay intact."""
import base64
import configparser
import copy
import ipaddress
import json
import os
from pathlib import Path
import re
import subprocess
import tempfile
import hashlib
import socket
import ssl
import time
import urllib.parse
import uuid

OWNER='SKYBYTE WARP routing v1'
MEDIA=['netflix.com','netflix.net','nflxext.com','nflximg.com','nflximg.net','nflxso.net','nflxvideo.net',
       'disneyplus.com','disney-plus.net','dssott.com','bamgrid.com','youtube.com','youtu.be','googlevideo.com','ytimg.com','youtubei.googleapis.com',
       'primevideo.com','amazonvideo.com','aiv-cdn.net','aiv-delivery.net','tiktok.com','tiktokv.com','tiktokcdn.com','tiktokcdn-us.com','byteoversea.com','ibytedtos.com']
AI=['openai.com','chatgpt.com','oaistatic.com','oaiusercontent.com','anthropic.com','claude.ai','claude.com',
    'gemini.google.com','aistudio.google.com','generativelanguage.googleapis.com']
PROFILES={'netflix':MEDIA[:7],'disney':MEDIA[7:11],'chatgpt':AI[:4],'gemini':AI[7:]}
RULE_VERSION='2026.10.23'
FIELDS=('route','outbounds')
RELAY_OWNER='SKYBYTE relay profile v1'

def relay_address(value):
    if not isinstance(value,str) or len(value)>253:raise ValueError('Invalid relay address')
    try:return str(ipaddress.ip_address(value))
    except ValueError:
        if not re.fullmatch(r'(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}',value):raise ValueError('Invalid relay hostname')
        return value.lower()

def relay_certificate(value,check_expiry=False):
    if not isinstance(value,str) or len(value)>65536 or 'PRIVATE KEY' in value:raise ValueError('Supply only a public relay certificate')
    blocks=re.findall(r'-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----',value,re.S)
    if not blocks or ''.join(value.split())!=''.join(''.join(blocks).split()):raise ValueError('Invalid public certificate PEM')
    fingerprints=[]
    for block in blocks:
        der=ssl.PEM_cert_to_DER_cert(block);fingerprints.append(hashlib.sha256(der).hexdigest())
    # Import only unexpired trust material. The live TLS probe verifies the peer/name.
    if check_expiry:
        with tempfile.TemporaryDirectory() as root:
            path=Path(root)/'public.pem';path.write_text(value)
            result=subprocess.run([os.environ.get('OPENSSL_BIN','openssl'),'x509','-in',str(path),'-noout','-checkend','0'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=10)
            if result.returncode:raise ValueError('Relay certificate expired or invalid')
    return blocks,fingerprints

def relay_normalize(outbound):
    if not isinstance(outbound,dict):raise ValueError('Expected one relay outbound')
    d=copy.deepcopy(outbound);kind=d.get('type')
    common={'type','tag','server','server_port','tls','network'}
    allowed=common|({'uuid','flow','packet_encoding'} if kind=='vless' else {'password','obfs','up_mbps','down_mbps','server_ports','hop_interval'} if kind=='hysteria2' else set())
    if kind not in ('vless','hysteria2') or set(d)-allowed:raise ValueError('Unsupported relay protocol or fields')
    d['server']=relay_address(d['server']);port=d['server_port']
    if type(port) is not int or not 1<=port<=65535:raise ValueError('Invalid relay port')
    if 'network' in d and d['network'] not in ('tcp','udp'):raise ValueError('Invalid relay network')
    d['tag']='skybyte-relay';tls=d.get('tls')
    if not isinstance(tls,dict) or set(tls)-{'enabled','server_name','insecure','utls','reality','certificate','certificate_path','alpn'} or tls.get('enabled') is not True or tls.get('insecure',False) is not False:raise ValueError('Relay TLS verification must be enabled')
    tls['server_name']=relay_address(tls.get('server_name',d['server']));tls['insecure']=False
    if 'alpn' in tls and (not isinstance(tls['alpn'],list) or not tls['alpn'] or any(x not in ('h2','http/1.1','h3') for x in tls['alpn'])):raise ValueError('Unsupported relay ALPN')
    if 'certificate_path' in tls:raise ValueError('Embed public trust certificate; external certificate paths are not imported')
    if kind=='vless':
        try:d['uuid']=str(uuid.UUID(d['uuid']))
        except (ValueError,TypeError,AttributeError):raise ValueError('Invalid relay UUID') from None
        if d.get('flow')!='xtls-rprx-vision' or d.get('packet_encoding','xudp')!='xudp':raise ValueError('Relay supports Reality + Vision with XUDP')
        r=tls.get('reality',{})
        if not isinstance(r,dict) or set(r)-{'enabled','public_key','short_id'} or r.get('enabled') is not True:raise ValueError('Reality verification is required')
        key=r.get('public_key','');sid=r.get('short_id','')
        if not re.fullmatch(r'[A-Za-z0-9_-]{43}',key) or len(base64.urlsafe_b64decode(key+'='))!=32 or not re.fullmatch(r'(?:[0-9a-fA-F]{2}){0,8}',sid):raise ValueError('Invalid Reality public key/short ID')
        u=tls.setdefault('utls',{'enabled':True,'fingerprint':'chrome'})
        if not isinstance(u,dict) or set(u)-{'enabled','fingerprint'} or u.get('enabled') is not True or u.get('fingerprint') not in ('chrome','firefox','edge','safari','ios','android','random','randomized'):raise ValueError('Invalid Reality fingerprint')
        if 'certificate' in tls:raise ValueError('Reality uses its public key, not a custom CA')
    else:
        if 'utls' in tls or 'reality' in tls:raise ValueError('Invalid HY2 TLS fields')
        password=d.get('password')
        if not isinstance(password,str) or not password or len(password)>1024 or any(ord(c)<32 for c in password):raise ValueError('Invalid HY2 password')
        if 'certificate' in tls:
            cert=tls['certificate']
            if not isinstance(cert,list) or not cert or any(not isinstance(x,str) for x in cert):raise ValueError('Invalid embedded public certificate')
            tls['certificate']=relay_certificate('\n'.join(cert))[0]
        for field in ('up_mbps','down_mbps'):
            if field in d and (type(d[field]) is not int or not 1<=d[field]<=100000):raise ValueError('Invalid HY2 relay bandwidth')
        if 'obfs' in d:
            ob=d['obfs']
            if not isinstance(ob,dict) or set(ob)!={'type','password'} or ob['type']!='salamander' or not isinstance(ob['password'],str) or not 1<=len(ob['password'])<=1024 or any(ord(c)<32 for c in ob['password']):raise ValueError('Invalid HY2 relay obfuscation')
        if 'server_ports' in d:
            ranges=d['server_ports']
            if not isinstance(ranges,list) or not 1<=len(ranges)<=20:raise ValueError('Invalid HY2 hopping ranges')
            total=0
            for item in ranges:
                if not isinstance(item,str) or not re.fullmatch(r'[0-9]{1,5}(?::[0-9]{1,5})?',item):raise ValueError('Invalid HY2 hopping range')
                parts=list(map(int,item.split(':')));start,end=parts[0],parts[-1]
                if not 1<=start<=end<=65535:raise ValueError('Invalid HY2 hopping range')
                total+=end-start+1
            if total>20001:raise ValueError('HY2 hopping range is too large')
        if 'hop_interval' in d and (not isinstance(d['hop_interval'],str) or not re.fullmatch(r'(?:[1-9][0-9]?|[1-5][0-9]{2}|600)s',d['hop_interval'])):raise ValueError('Invalid HY2 hopping interval')
    return d

def relay_import(source,trust=''):
    p=Path(source)
    if p.is_symlink() or not p.is_file() or p.stat().st_size>131072:raise ValueError('Invalid relay source file')
    text=p.read_text().strip();pin=''
    if text.startswith('{'):
        d=json.loads(text)
        if 'outbounds' in d:
            choices=[o for o in d['outbounds'] if o.get('type')!='direct']
            if len(choices)!=1:raise ValueError('Supply exactly one landing node')
            d=choices[0]
    else:
        if len(text)>8192 or any(ord(c)<32 for c in text) or re.search(r'%(?![0-9a-fA-F]{2})',text):raise ValueError('Invalid node link')
        u=urllib.parse.urlsplit(text);pairs=urllib.parse.parse_qsl(u.query,keep_blank_values=True)
        if len(dict(pairs))!=len(pairs):raise ValueError('Duplicate node link parameters')
        q=dict(pairs)
        if any(q.get(x,'0').lower() not in ('0','false') for x in ('insecure','allowInsecure','skip-cert-verify')):raise ValueError('Unsafe relay TLS link rejected')
        if u.scheme=='vless' and '@' not in u.netloc:
            authority=base64.b64decode(u.netloc+'='*(-len(u.netloc)%4),altchars=b'-_',validate=True).decode()
            if not authority.startswith('auto:'):raise ValueError('Unsupported native VLESS authority')
            u=urllib.parse.urlsplit('vless://'+authority[5:])
            if q.get('xtls')!='2' or q.get('tls') not in ('1','2'):raise ValueError('Only Reality/Vision native links are supported')
            q.update(security='reality',flow='xtls-rprx-vision',sni=q.get('peer',''))
        if u.path not in ('','/') or u.port is None or not u.hostname or '@' not in u.netloc:raise ValueError('Node credentials, address and port are required')
        tls={'enabled':True,'insecure':False,'server_name':q.get('sni') or q.get('peer') or u.hostname}
        d={'type':u.scheme,'server':u.hostname,'server_port':u.port,'tls':tls}
        if u.scheme=='vless':
            if q.get('security')!='reality' or q.get('type','tcp')!='tcp' or q.get('encryption','none')!='none':raise ValueError('Only VLESS Reality/Vision TCP links are supported')
            d.update(uuid=urllib.parse.unquote(u.username or ''),flow=q.get('flow',''))
            tls.update(reality={'enabled':True,'public_key':q.get('pbk',''),'short_id':q.get('sid','')},utls={'enabled':True,'fingerprint':q.get('fp','chrome')})
            allowed={'encryption','flow','security','sni','fp','pbk','sid','type','remarks','peer','tls','xtls','insecure','allowInsecure','skip-cert-verify'}
        elif u.scheme in ('hysteria2','hy2'):
            d['type']='hysteria2';d['password']=urllib.parse.unquote(u.netloc.rsplit('@',1)[0]);pin=q.get('pinSHA256','').replace(':','').lower()
            if 'obfs' in q:d['obfs']={'type':q['obfs'],'password':q.get('obfs-password','')}
            if 'mport' in q:d.update(server_ports=q['mport'].replace('-',':').split(','),hop_interval='30s')
            allowed={'sni','peer','insecure','allowInsecure','skip-cert-verify','pinSHA256','obfs','obfs-password','mport'}
        else:raise ValueError('Landing node must use Reality/Vision or HY2')
        if set(q)-allowed:raise ValueError('Unsupported node link parameters; use a single sing-box outbound JSON')
    if trust:
        if d.get('type')!='hysteria2':raise ValueError('Public trust certificate is only used for HY2')
        p=Path(trust)
        if p.is_symlink() or not p.is_file() or p.stat().st_size>65536:raise ValueError('Invalid public certificate file')
        blocks,fingerprints=relay_certificate(p.read_text(),True)
        if pin and (not re.fullmatch('[0-9a-f]{64}',pin) or pin not in fingerprints):raise ValueError('Relay certificate fingerprint mismatch')
        d['tls']['certificate']=blocks
    elif pin:raise ValueError('Pinned HY2 link requires the matching public certificate file')
    result=relay_normalize(d)
    if result['tls'].get('certificate'):relay_certificate('\n'.join(result['tls']['certificate']),True)
    return result

def relay_profile(path):
    p=Path(path)
    if p.is_symlink() or not p.is_file() or p.stat().st_size>131072:raise ValueError('Invalid private relay profile')
    d=json.loads(p.read_text())
    if d.get('owner')!=RELAY_OWNER or d.get('schema')!=1:raise ValueError('Relay profile ownership mismatch')
    return relay_normalize(d['outbound'])

def relay_probe(outbound,binary):
    outbound=relay_normalize(outbound)
    with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
    with tempfile.TemporaryDirectory() as root:
        p=Path(root)/'probe.json'
        cfg={'log':{'disabled':True},'inbounds':[{'type':'socks','listen':'127.0.0.1','listen_port':port}], 'outbounds':[outbound], 'route':{'final':'skybyte-relay'}}
        p.write_text(json.dumps(cfg));p.chmod(0o600)
        result=subprocess.run([binary,'check','-c',str(p)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=30)
        if result.returncode:raise ValueError('Relay configuration failed validation')
        proc=subprocess.Popen([binary,'run','-c',str(p)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        try:
            deadline=time.monotonic()+5
            while True:
                if proc.poll() is not None:raise ValueError('Relay test core failed to start')
                try:
                    with socket.create_connection(('127.0.0.1',port),timeout=.2):break
                except OSError:
                    if time.monotonic()>deadline:raise ValueError('Relay test listener unavailable') from None
                    time.sleep(.1)
            result=subprocess.run(['curl','-q','-fsS','--noproxy','','--proxy','socks5h://127.0.0.1:'+str(port),'--proto','=https','--max-time','15','--max-filesize','65536','https://www.cloudflare.com/cdn-cgi/trace'],capture_output=True,timeout=20,text=True)
            if result.returncode:raise ValueError('Landing TLS/authentication/HTTPS connection test failed')
            fields=dict(line.split('=',1) for line in result.stdout.splitlines() if '=' in line)
            try:ip=str(ipaddress.ip_address(fields['ip']))
            except (ValueError,KeyError):raise ValueError('Landing egress address was not verified') from None
            return ip
        finally:
            if proc.poll() is None:proc.terminate()
            try:proc.wait(timeout=5)
            except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=5)

def atomic(path,data):
    path=Path(path)
    if path.is_symlink():raise ValueError('Refusing WARP symlink')
    fd,tmp=tempfile.mkstemp(dir=path.parent)
    try:
        with os.fdopen(fd,'w') as f:json.dump(data,f,indent=2);f.flush();os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def read_state(base):
    p=base/'warp-state.json'
    if p.is_symlink():raise ValueError('WARP state is a symlink')
    if not p.exists():return None
    d=json.loads(p.read_text())
    if d.get('owner')!=OWNER or d.get('schema')!=1 or d['mode'] not in ('direct','restricted','global'):raise ValueError('WARP state ownership/schema mismatch')
    provider=d.get('provider','warp')
    if provider not in ('warp','relay'):raise ValueError('Invalid outbound provider')
    if type(d['port']) is not int or not (1 if provider=='relay' else 1024)<=d['port']<=65535 or type(d['udp']) is not bool:raise ValueError('Invalid outbound settings')
    if 'relay' in d:relay_normalize(d['relay'])
    if provider=='relay' and 'relay' not in d:raise ValueError('Missing landing profile')
    return d

def status_text(state,language='en_US'):
    zh=language=='zh_CN'
    if not state:return '当前状态：未配置 WARP' if zh else 'Status: WARP not configured'
    if state.get('provider','warp')!='warp':return '当前状态：WARP 未启用（当前使用落地中转）' if zh else 'Status: WARP inactive (relay selected)'
    modes={'direct':('已关闭 WARP 分流，当前直连','Direct; WARP routing disabled'),
           'restricted':('仅指定域名使用 WARP','Selected domains use WARP'),
           'global':('全部节点流量使用 WARP','All node traffic uses WARP')}
    mode=modes[state['mode']][0 if zh else 1]
    proxy=('本机代理：' if zh else 'Local proxy: ')+'127.0.0.1:'+str(state['port'])
    udp=('支持' if state['udp'] else '不支持') if zh else ('supported' if state['udp'] else 'unsupported')
    return ('当前模式：' if zh else 'Routing: ')+mode+'\n'+proxy+' | UDP: '+udp

def view(cfg):return {k:copy.deepcopy(cfg.get(k)) for k in FIELDS}

def put(cfg,routing):
    for k,v in routing.items():
        if v is None:cfg.pop(k,None)
        else:cfg[k]=copy.deepcopy(v)
    return cfg

def render(baseline,mode,port,udp,domains,relay=None):
    result=copy.deepcopy(baseline)
    if mode=='direct':return result
    tag='skybyte-relay' if relay else 'skybyte-warp'
    result['outbounds'].append(relay_normalize(relay) if relay else {'type':'socks','tag':tag,'server':'127.0.0.1','server_port':port,'version':'5',**({} if udp else {'network':'tcp'})})
    route=result['route'];prefix=[]
    if mode=='restricted':
        prefix=[{'action':'sniff','timeout':'500ms'}]
        if not udp:prefix.append({'domain_suffix':domains,'network':'udp','action':'reject'})
        prefix.append({'domain_suffix':domains,'action':'route','outbound':tag})
    else:
        route['final']=tag
        if not udp:prefix=[{'network':'udp','action':'reject'}]
    route['rules']=prefix+route.get('rules',[])
    return result

def config_paths(base,conf):
    paths=[conf]
    if (base/'argo-state.json').exists():paths.append(base/'argo-server.json')
    if (base/'users.json').exists():
        users=json.loads((base/'users.json').read_text())
        if users.get('owner')!='SKYBYTE user quotas v1':raise ValueError('Invalid user owner')
        for u in users['users']:
            if not re.fullmatch('[0-9a-f]{16}',u['id']):raise ValueError('Invalid account ID')
            if not u.get('deleted'):paths.append(base/'users'/u['id']/'server.json')
    for p in paths:
        if p.is_symlink() or p.parent.is_symlink():raise ValueError('Config symlink')
    return paths

def domains_parse(text):
    domains=sorted(set(text.replace(',', ' ').split()))
    if not domains or len(domains)>200 or any(len(x)>253 or not re.fullmatch(r'(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}',x) for x in domains):raise ValueError('Invalid domain suffix list')
    return sorted(set(d.lower() for d in domains))

def catalog(base):
    path=base/'warp-rules.json'
    if path.is_symlink():raise ValueError('Rule catalog symlink')
    d=json.loads(path.read_text()) if path.exists() else {'owner':'SKYBYTE WARP rules v1','schema':1,'version':RULE_VERSION,'media':MEDIA,'ai':AI}
    validate_catalog(d)
    return d

def validate_catalog(d):
    if d.get('owner')!='SKYBYTE WARP rules v1' or d.get('schema')!=1 or not re.fullmatch(r'[0-9]{4}\.[0-9]{2}\.[0-9]{2}(?:\.[0-9]+)?',d.get('version','')):raise ValueError('Invalid rule catalog')
    if not isinstance(d['media'],list) or not isinstance(d['ai'],list) or any(not isinstance(x,str) for x in d['media']+d['ai']):raise ValueError('Invalid catalog suffixes')
    domains_parse(' '.join(d['media']+d['ai']))


def switch(base,conf,binary,mode,port,udp,domains,relay=None):
    if mode not in ('direct','restricted','global') or not (1 if relay else 1024)<=port<=65535:raise ValueError('Invalid outbound mode/port')
    if relay:
        relay=relay_normalize(relay)
        names={'127.0.0.1','::1','localhost'}
        for p in (base/'state.json',):
            if p.exists():names.add(json.loads(p.read_text()).get('ip','').lower())
        for p in config_paths(base,conf):
            cfg=json.loads(p.read_text())
            if relay['server'].lower() in names and any(i.get('listen_port')==relay['server_port'] for i in cfg.get('inbounds',[])):raise ValueError('Landing points back to a managed listener')
    prior=read_state(base)
    state=copy.deepcopy(prior) if prior else {'owner':OWNER,'schema':1,'configs':{}}
    originals={};planned={}
    for path in config_paths(base,conf):
        cfg=json.loads(path.read_text());originals[path]=cfg
        old=state['configs'].get(str(path))
        if old:
            if view(cfg)!=old['applied']:raise ValueError('Routing changed outside manager; refusing overwrite: '+str(path))
            baseline=old['baseline']
        else:
            if cfg.get('endpoints') or any(o['type']!='direct' for o in cfg['outbounds']) or cfg['route'].get('final')!='direct':raise ValueError('Unmanaged routing; refusing overwrite')
            baseline=view(cfg)
        if relay and mode!='direct' and baseline.get('route',{}).get('rules'):raise ValueError('Custom baseline routing requires manual review before relay')
        routing=render(baseline,mode,port,udp,domains,relay)
        candidate=put(copy.deepcopy(cfg),routing)
        fd,tmp=tempfile.mkstemp(dir=path.parent)
        try:
            with os.fdopen(fd,'w') as f:json.dump(candidate,f)
            r=subprocess.run([binary,'check','-c',tmp],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=30)
            if r.returncode:raise ValueError('WARP candidate config failed validation')
        finally:os.unlink(tmp)
        planned[path]=candidate;state['configs'][str(path)]={'baseline':baseline,'applied':routing}
    state.update(mode=mode,port=port,udp=udp,domains=domains,provider='relay' if relay else 'warp')
    if relay:state['relay']=relay
    try:
        for p,cfg in planned.items():atomic(p,cfg)
        atomic(base/'warp-state.json',state)
    except BaseException:
        for p,cfg in originals.items():atomic(p,cfg)
        if prior:atomic(base/'warp-state.json',prior)
        elif (base/'warp-state.json').exists():(base/'warp-state.json').unlink()
        raise

def restore_routing(base,conf,snapshot,binary):
    saved=snapshot/'warp-state.json'
    new=json.loads(saved.read_text()) if saved.exists() else None
    if saved.is_symlink():raise ValueError('Backup state symlink')
    prior=read_state(base)
    originals={}
    if new and (new.get('owner')!=OWNER or new.get('schema')!=1):raise ValueError('Invalid WARP backup')
    if new and 'relay' in new:relay_normalize(new['relay'])
    if new and new.get('provider')=='relay' and 'relay' not in new:raise ValueError('Relay backup has no landing profile')
    planned={}
    for path in config_paths(base,conf):
        if path==conf:source=snapshot/'config'/'config.json'
        elif path==base/'argo-server.json':source=snapshot/'argo-server.json'
        else:source=snapshot/'users'/path.parent.name/'server.json'
        current=json.loads(path.read_text());originals[path]=copy.deepcopy(current)
        if source.exists():
            if source.is_symlink():raise ValueError('Backup symlink')
            routing=view(json.loads(source.read_text()))
        else:
            old=prior['configs'].get(str(path)) if prior else None
            if old:
                if view(current)!=old['applied']:raise ValueError('New account routing changed; refusing overwrite')
                baseline=old['baseline']
            else:
                if any(o['type']!='direct' for o in current['outbounds']):raise ValueError('Unmanaged new account routing')
                baseline=view(current)
            routing=render(baseline,new['mode'],new['port'],new['udp'],new['domains'],new.get('relay') if new.get('provider')=='relay' else None) if new else baseline
            if new:new['configs'][str(path)]={'baseline':baseline,'applied':routing}
        planned[path]=put(current,routing)
    for path,cfg in planned.items():
        fd,tmp=tempfile.mkstemp(dir=path.parent)
        try:
            with os.fdopen(fd,'w') as f:json.dump(cfg,f)
            r=subprocess.run([binary,'check','-c',tmp],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=30)
            if r.returncode:raise ValueError('Restored WARP config failed validation')
        finally:os.unlink(tmp)
    try:
        for path,cfg in planned.items():
            if cfg!=originals[path]:atomic(path,cfg)
        if new:atomic(base/'warp-state.json',new)
        elif (base/'warp-state.json').exists():(base/'warp-state.json').unlink()
    except BaseException:
        for path,cfg in originals.items():atomic(path,cfg)
        if prior:atomic(base/'warp-state.json',prior)
        raise

def gateway(profile,port,target,binary,family='auto'):
    if family not in ('auto','4','6'):raise ValueError('Invalid native gateway family')
    p=configparser.ConfigParser(interpolation=None,strict=True)
    try:
        with open(profile) as f:p.read_file(f)
    except configparser.Error:raise ValueError('Invalid WireGuard profile') from None
    if set(p.sections())!={'Interface','Peer'}:raise ValueError('Expected one Interface and Peer')
    if set(p['Interface'])-{'privatekey','address','dns','mtu','listenport'} or set(p['Peer'])-{'publickey','allowedips','endpoint','persistentkeepalive','reserved'}:raise ValueError('Unsupported profile directives; scripts are never executed')
    a=p['Interface'];b=p['Peer']
    for key in (a['privatekey'],b['publickey']):
        if len(base64.b64decode(key,validate=True))!=32:raise ValueError('Invalid WireGuard key')
    addresses=[str(ipaddress.ip_interface(x.strip())) for x in a['address'].split(',')]
    allowed=[str(ipaddress.ip_network(x.strip(),strict=False)) for x in b['allowedips'].split(',')]
    if {ipaddress.ip_interface(x).version for x in addresses}!={4,6} or set(allowed)!={'0.0.0.0/0','::/0'}:raise ValueError('A dual-stack WARP profile is required')
    endpoint=b['endpoint'].strip();match=re.fullmatch(r'(?:\[([^]]+)\]|([^:\s]+)):(\d+)',endpoint)
    if not match:raise ValueError('Invalid peer Endpoint')
    address=relay_address(match[1] or match[2]);peer_port=int(match[3])
    try:
        native=ipaddress.ip_address(address)
        if family!='auto' and native.version!=int(family):raise ValueError('WireGuard Endpoint does not match native connectivity; supply a reachable peer IP')
    except ValueError:
        # Distinguish a hostname from a numeric endpoint in the wrong family.
        if re.fullmatch('[0-9a-fA-F:.]+',address):raise
    if not 1<=peer_port<=65535:raise ValueError('Invalid peer port')
    reserved=[int(x.strip()) for x in b.get('reserved','0,0,0').split(',')]
    if len(reserved)!=3 or any(not 0<=x<=255 for x in reserved):raise ValueError('Invalid reserved bytes')
    mtu=int(a.get('mtu','1280'));listen=int(a.get('listenport','0'))
    if not 1280<=mtu<=9000 or not 0<=listen<=65535:raise ValueError('Invalid MTU/listen port')
    cfg={'log':{'level':'warn'},'inbounds':[{'type':'socks','tag':'warp-local','listen':'127.0.0.1','listen_port':port}],
         'outbounds':[{'type':'direct','tag':'direct'}],
         'endpoints':[{'type':'wireguard','tag':'warp-wg','system':False,'address':addresses,'private_key':a['privatekey'],'listen_port':listen,'mtu':mtu,
                       'peers':[{'address':address,'port':peer_port,'public_key':b['publickey'],'allowed_ips':allowed,'reserved':reserved,'persistent_keepalive_interval':int(b.get('persistentkeepalive','25'))}]}],
         'dns':{'servers':[{'type':'https','tag':'warp-dns','server':'1.1.1.1','path':'/dns-query','detour':'warp-wg'},{'type':'local','tag':'bootstrap'}]},
         'route':{'final':'warp-wg','default_domain_resolver':'warp-dns'}}
    try:ipaddress.ip_address(address)
    except ValueError:cfg['endpoints'][0]['domain_resolver']={'server':'bootstrap',**({'strategy':'ipv'+family+'_only'} if family!='auto' else {})}
    fd,tmp=tempfile.mkstemp(dir=target.parent)
    try:
        with os.fdopen(fd,'w') as f:json.dump(cfg,f)
        r=subprocess.run([binary,'check','-c',tmp],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=30)
        if r.returncode:raise ValueError('Gateway config failed validation')
        atomic(target,cfg)
    finally:os.unlink(tmp)

if __name__=='__main__':
    import sys
    base,conf,binary,action,*args=sys.argv[1:];base=Path(base);conf=Path(conf)
    if action=='switch':switch(base,conf,binary,args[0],int(args[1]),args[2]=='true',domains_parse(args[3]))
    elif action=='reconcile':
        s=read_state(base)
        if s:switch(base,conf,binary,s['mode'],s['port'],s['udp'],s['domains'],s.get('relay') if s.get('provider')=='relay' else None)
    elif action.startswith('relay_'):
        try:
            if action=='relay_prepare':atomic(args[1],{'owner':RELAY_OWNER,'schema':1,'outbound':relay_import(args[0],args[2])})
            elif action=='relay_export':
                s=read_state(base)
                if not s or 'relay' not in s:raise ValueError('No landing node configured')
                atomic(args[0],{'owner':RELAY_OWNER,'schema':1,'outbound':s['relay']})
            elif action=='relay_probe':print(relay_probe(relay_profile(args[0]),binary))
            elif action=='relay_switch':
                r=relay_profile(args[1]);switch(base,conf,binary,args[0],r['server_port'],r.get('network')!='tcp',domains_parse(args[2]),r)
            elif action=='relay_status':
                s=read_state(base)
                zh=bool(args and args[0]=='zh_CN')
                if not s or 'relay' not in s:print('尚未配置落地节点' if zh else 'Relay: not configured')
                else:
                    r=relay_normalize(s['relay']);mode=s['mode'] if s.get('provider')=='relay' else 'inactive'
                    print(('中转：' if zh else 'Relay: ')+r['type']+' | '+r['server']+':'+str(r['server_port'])+(' | TLS 验证：开启 | ' if zh else ' | TLS verification: on | ')+({'global':'全局中转','restricted':'指定域名中转','direct':'已恢复直连','inactive':'中转未启用'}[mode] if zh else mode))
                    for cert in r['tls'].get('certificate',[]):print(('公开证书 SHA256：' if zh else 'Public certificate SHA256: ')+hashlib.sha256(ssl.PEM_cert_to_DER_cert(cert)).hexdigest())
            elif action=='relay_forget':
                s=read_state(base)
                if s and 'relay' in s:
                    if s.get('provider')=='relay' and s['mode']!='direct':raise ValueError('Disable relay routing before removing its profile')
                    s.pop('relay')
                    if s.get('provider')=='relay':s['provider']='warp';s['port']=40000
                    atomic(base/'warp-state.json',s)
            else:raise ValueError('Unknown relay action')
        except (ValueError,KeyError,TypeError,OSError,subprocess.SubprocessError):
            raise SystemExit('Relay operation failed; check protocol fields, trusted certificate and landing connectivity. TLS verification remains required.') from None
    elif action=='restore':restore_routing(base,conf,Path(args[0]),binary)
    elif action=='gateway':gateway(args[0],int(args[1]),base/'warp-gateway.json',binary,args[2] if len(args)>2 else 'auto')
    elif action=='port':
        state=read_state(base)
        if not state or state.get('provider','warp')!='warp':raise ValueError('WARP routing is not configured; current provider is relay')
        print(state['port'])
    elif action=='status':
        state=read_state(base)
        print(status_text(state,args[0] if args else 'en_US'))
    elif action=='forget_argo':
        state=read_state(base)
        if state:
            state['configs'].pop(str(base/'argo-server.json'),None);atomic(base/'warp-state.json',state)
    elif action=='defaults':
        d=catalog(base);print(' '.join(d['media']+d['ai']))
    elif action=='profile':
        print(' '.join(PROFILES[args[0]] if args[0]!='all' else sum(PROFILES.values(),[])))
    elif action=='catalog_status':
        d=catalog(base);print('WARP rules: '+d['version']+' | suffixes: '+str(len(domains_parse(' '.join(d['media']+d['ai'])))))
    elif action=='catalog_update':
        p=Path(args[0])
        if p.is_symlink() or p.stat().st_size>65536:raise ValueError('Invalid catalog file')
        d=json.loads(p.read_text());validate_catalog(d)
        current=catalog(base)
        if tuple(map(int,d['version'].split('.'))) < tuple(map(int,current['version'].split('.'))):raise ValueError('Older catalog refused')
        atomic(base/'warp-rules.previous.json',current);atomic(base/'warp-rules.json',d)
        print('WARP rules: '+d['version'])
    elif action=='guard':read_state(base)
    else:raise ValueError('Unknown WARP action')
PY_WARP
}
warp_guard(){
 local file unit=$SYSTEMD_DIR/skybyte-warp-gateway.service
 for file in warp-state.json warp-gateway.json warp-client.json warp-rules.json warp-rules.previous.json; do [[ ! -L $BASE/$file ]] || return 1; done
 if [[ -e $unit || -L $unit ]]; then
  if [[ -L $unit ]] || ! grep -Fxq 'Description=SKYBYTE managed WARP gateway' "$unit" || ! grep -Fxq "ExecStart=$BIN run -c $BASE/warp-gateway.json" "$unit"; then err "$(L 'WARP 网关归属异常' 'WARP gateway ownership mismatch')"; return 1; fi
 fi
 if [[ -f $BASE/warp-gateway.json && ! -f $unit ]]; then err "$(L '已有非托管网关配置，拒绝覆盖' 'Unmanaged gateway config exists; refusing overwrite')"; return 1; fi
 if [[ -f $BASE/warp-client.json ]]; then python3 - "$BASE/warp-client.json" <<'PY_WARP_OWNER'
import json,sys
s=json.load(open(sys.argv[1]));assert s['owner']=='SKYBYTE WARP client v1' and type(s['port']) is int and 1024<=s['port']<=65535
PY_WARP_OWNER
 fi
 warp_engine guard
}
warp_verify(){
 local port=$1 trace
 valid_port "$port" && ((10#$port>=1024)) || return 1
 trace=$(curl -q -fsSL --noproxy '' --proxy "socks5h://127.0.0.1:$port" --proto '=https' --proto-redir '=https' --max-time 12 --max-filesize 65536 https://www.cloudflare.com/cdn-cgi/trace) || { err "$(L 'WARP 代理连接失败' 'WARP proxy connection failed')"; return 1; }
 local egress
 egress=$(printf '%s\n' "$trace" | python3 -c 'import ipaddress,re,sys; d=dict(line.split("=",1) for line in sys.stdin.read().splitlines() if "=" in line); assert d.get("warp") in ("on","plus") and ipaddress.ip_address(d.get("ip","")).is_global and re.fullmatch("[A-Z]{2}",d.get("loc","")); print(d["ip"]+" ("+d["loc"]+")")' 2>/dev/null) || { err "$(L '代理未通过 WARP 出口验证，拒绝应用' 'Proxy did not verify as WARP; refusing apply')"; return 1; }
 ok "$(L 'WARP 出口验证通过：' 'WARP egress verified: ')$egress"
}
warp_wait_ready(){
 local port=$1 attempt
 say '等待 WARP 本机代理就绪……' 'Waiting for the WARP local proxy…'
 for ((attempt=0;attempt<3;attempt++)); do
  if warp_loopback "$port" && warp_verify "$port"; then return 0; fi
  [[ $attempt == 2 ]] || sleep 2
 done
 err "$(L 'WARP 尚未就绪，节点分流保持原样；可稍后使用现有本机代理选项重试' 'WARP is not ready; node routing is unchanged. Retry using the existing local proxy option later')"
 return 1
}
warp_loopback(){
 local port=$1 listeners address
 valid_port "$port" && ((10#$port>=1024)) || return 1
 require_cmd ss || return 1
 listeners=$(ss -H -ltn "( sport = :$port )") || return 1
 [[ -n $listeners ]] || { err "$(L '本地代理未监听' 'Local proxy is not listening')"; return 1; }
 while read -r address; do
  case $address in "127.0.0.1:$port"|"[::1]:$port"|"::1:$port") ;; *) err "$(L 'WARP 代理必须只监听回环地址' 'WARP proxy must listen only on loopback')"; return 1;; esac
 done < <(printf '%s\n' "$listeners" | awk '{print $4}')
}
warp_resume(){
 local admin=$1 argo=$2 users=$3
 if [[ $admin == true ]]; then systemctl restart sing-box.service && service_healthy || return 1; fi
 if [[ $argo == true ]]; then systemctl restart skybyte-argo-node.service && systemctl is-active --quiet skybyte-argo-node.service || return 1; fi
 if [[ $users == true ]]; then systemctl start skybyte-users.service && systemctl is-active --quiet skybyte-users.service || return 1; fi
}
warp_switch(){
 local mode=$1 port=$2 udp=$3 domains=$4 snap admin=false argo=false users=false
 check_owned && warp_guard && users_guard && argo_guard || return 1
 if [[ $mode != direct ]]; then warp_loopback "$port" && warp_verify "$port" || return 1; fi
 snap=$(backup) || return 1
 if systemctl is-active --quiet sing-box.service; then admin=true; fi
 if [[ -f $BASE/argo-state.json ]] && systemctl is-active --quiet skybyte-argo-node.service; then argo=true; fi
 if [[ -f $BASE/users.json ]] && systemctl is-active --quiet skybyte-users.service; then users=true; users_stop || return 1; fi
 if ! warp_engine switch "$mode" "$port" "$udp" "$domains"; then warp_resume "$admin" "$argo" "$users" || :; return 1; fi
 if ! warp_resume "$admin" "$argo" "$users"; then
  [[ $users != true ]] || users_stop || :
  warp_engine restore "$snap" || return 1
  warp_resume "$admin" "$argo" "$users" || :
  err "$(L 'WARP 分流重启失败，已回滚路由' 'WARP restart failed; routing rolled back')"; return 1
 fi
 ok "$(L '已应用出站模式：' 'Outbound mode applied: ')$mode"
 say "备份：$snap" "Backup: $snap"
}
warp_proxy_capability(){
 python3 - "$1" <<'PY_SOCKS_CAP'
import socket,struct,sys
port=int(sys.argv[1]);assert 1024<=port<=65535
with socket.create_connection(('127.0.0.1',port),timeout=3) as s:
 def read_exact(n):
  data=b''
  while len(data)<n:
   part=s.recv(n-len(data))
   if not part:raise ConnectionError('SOCKS reply ended early')
   data+=part
  return data
 s.sendall(b'\x05\x01\x00');hello=read_exact(2)
 if hello!=b'\x05\x00':raise ValueError('SOCKS5 no-auth handshake failed')
 s.sendall(b'\x05\x03\x00\x01'+socket.inet_aton('127.0.0.1')+struct.pack('!H',0))
 try:reply=read_exact(4)
 except (TimeoutError,ConnectionError):reply=b''
 print('true' if reply[:2]==b'\x05\x00' else 'false')
PY_SOCKS_CAP
}
warp_install_client(){
 need_root; check_owned && warp_guard || return 1
 local os_id code port tmp registration
 if command -v warp-cli >/dev/null; then err "$(L '已有 WARP 客户端，请用现有本机代理选项，避免覆盖其设置' 'WARP client exists; use the existing local proxy option to preserve its settings')"; return 1; fi
 if [[ -e ${WARP_DATA_DIR:-/var/lib/cloudflare-warp} || -L ${WARP_DATA_DIR:-/var/lib/cloudflare-warp} ]]; then err "$(L '发现已有 WARP 数据，请先手动核对注册与模式，避免启动已有全局连接' 'Existing WARP data found; inspect registration and mode before starting a potentially global connection')"; return 1; fi
 # shellcheck source=/dev/null
 . "$OS_RELEASE"
 os_id=${ID:-};code=${VERSION_CODENAME:-}
 case "$os_id:$code" in ubuntu:jammy|ubuntu:noble|ubuntu:resolute|debian:bookworm|debian:trixie) ;; *) err "$(L '自动安装 WARP 仅支持当前官方 Ubuntu/Debian 版本' 'Automatic WARP install requires a currently supported Ubuntu/Debian release')"; return 1;; esac
 for tmp in "$WARP_REPO_FILE" "$WARP_KEY_FILE"; do
  [[ ! -e $tmp && ! -L $tmp ]] || { err "$(L 'WARP 软件源文件已存在，拒绝覆盖' 'WARP repository file exists; refusing overwrite')"; return 1; }
 done
 say 'WARP 连接 Cloudflare；请阅读条款 https://www.cloudflare.com/application/terms/ 。不会切换系统默认路由。' 'WARP connects to Cloudflare. Terms: https://www.cloudflare.com/application/terms/ . System default routes are not switched.'
 confirm "$(L '安装官方客户端并注册、接受 WARP 服务条款？' 'Install/register the official client and accept WARP terms?')" || return 0
 prompt_read "$(L '本机代理端口 [40000]：' 'Local proxy port [40000]: ')" port || return 0; port=${port:-40000}
 valid_port "$port" && ((10#$port>=1024)) || return 1; port=$((10#$port))
 haproxy_engine check_port "$port" || return 1
 if ss -H -ltn "( sport = :$port )" | grep -q .; then err "$(L '端口已被占用' 'Port already occupied')"; return 1; fi
 apt_install curl ca-certificates gnupg || return 1
 tmp=$(mktemp -d "$BASE/warp-install.XXXXXX") || return 1
 if ! curl -q -fsSL --proto '=https' --max-time 30 https://pkg.cloudflareclient.com/pubkey.gpg -o "$tmp/key" ||
    ! gpg --batch --yes --dearmor --output "$tmp/keyring" "$tmp/key"; then rm -rf "$tmp"; return 1; fi
 command install -m 644 "$tmp/keyring" "$WARP_KEY_FILE" || { rm -rf "$tmp"; return 1; }
 printf 'deb [signed-by=%s] https://pkg.cloudflareclient.com/ %s main\n' "$WARP_KEY_FILE" "$code" > "$WARP_REPO_FILE"
 chmod 644 "$WARP_REPO_FILE"; rm -rf "$tmp"
 apt_install cloudflare-warp || return 1
 systemctl enable --now warp-svc.service || return 1
 if warp-cli --accept-tos registration show >/dev/null 2>&1; then err "$(L '发现已有 WARP 注册信息，保留不修改；请手动配置本机代理' 'Existing WARP registration found; retained. Configure a local proxy manually.')"; return 1; fi
 warp-cli --accept-tos registration new >/dev/null && warp-cli --accept-tos mode proxy && warp-cli --accept-tos proxy port "$port" && warp-cli --accept-tos connect || return 1
 registration=$(warp-cli --accept-tos registration show | sha256sum | awk '{print $1}') || return 1
 python3 - "$BASE/warp-client.json" "$port" "$registration" <<'PY_CLIENT_OWNER'
import json,os,sys,tempfile
fd,tmp=tempfile.mkstemp(dir=os.path.dirname(sys.argv[1]))
with os.fdopen(fd,'w') as f:json.dump({'owner':'SKYBYTE WARP client v1','port':int(sys.argv[2]),'registration_hash':sys.argv[3]},f)
os.replace(tmp,sys.argv[1])
PY_CLIENT_OWNER
 warp_wait_ready "$port" || return 1
 local udp domains
 udp=$(warp_proxy_capability "$port") || return 1; domains=$(warp_engine defaults) || return 1
 warp_switch restricted "$port" "$udp" "$domains"
}
warp_import_gateway(){
 check_owned && warp_guard || return 1
 local profile port saved active=false udp=true domains native=${1:-auto} routing=${2:-restricted}
 [[ $native == auto || $native == 4 || $native == 6 ]] && [[ $routing == global || $routing == restricted ]] || return 1
 prompt_read "$(L '已有 WARP WireGuard 配置路径（私密文件）：' 'Existing WARP WireGuard profile path (private): ')" profile || return 0
 [[ -f $profile && ! -L $profile ]] || return 1
 prompt_read "$(L '共享本机代理端口 [40000]：' 'Shared local proxy port [40000]: ')" port || return 0; port=${port:-40000}
 valid_port "$port" && ((10#$port>=1024)) || return 1; port=$((10#$port))
 haproxy_engine check_port "$port" || return 1
 confirm "$(L '导入私密配置并建立共享 WARP 网关？已有网关会短暂重启。' 'Import private profile and create shared WARP gateway? Existing gateway briefly restarts.')" || return 0
 saved=$(mktemp -d "$BASE/warp-import.XXXXXX") || return 1
 if [[ -f $BASE/warp-gateway.json ]]; then cp "$BASE/warp-gateway.json" "$saved/gateway.json" || return 1; fi
 if [[ -f $SYSTEMD_DIR/skybyte-warp-gateway.service ]]; then cp "$SYSTEMD_DIR/skybyte-warp-gateway.service" "$saved/unit" || return 1; fi
 if systemctl is-active --quiet skybyte-warp-gateway.service; then active=true; fi
 if ss -H -ltn "( sport = :$port )" | grep -q .; then
  if [[ $active != true ]] || [[ $(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["inbounds"][0]["listen_port"])' "$BASE/warp-gateway.json") != "$port" ]]; then rm -rf "$saved";err "$(L '代理端口已被占用' 'Proxy port occupied')";return 1;fi
 fi
 if ! warp_engine gateway "$profile" "$port" "$native"; then rm -rf "$saved"; return 1; fi
 if [[ $active == true ]]; then if ! systemctl stop skybyte-warp-gateway.service; then cp "$saved/gateway.json" "$BASE/warp-gateway.json";rm -rf "$saved";return 1;fi;fi
 cat >"$SYSTEMD_DIR/skybyte-warp-gateway.service" <<UNIT
[Unit]
Description=SKYBYTE managed WARP gateway
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$BIN run -c $BASE/warp-gateway.json
Restart=on-failure
RestartSec=5
LimitNOFILE=1048576
UMask=0077
[Install]
WantedBy=multi-user.target
UNIT
 if ! systemctl daemon-reload || ! systemctl enable --now skybyte-warp-gateway.service || ! { sleep 2; warp_loopback "$port" && warp_verify "$port"; }; then
  systemctl stop skybyte-warp-gateway.service || :
  if [[ -f $saved/gateway.json ]]; then cp "$saved/gateway.json" "$BASE/warp-gateway.json"; else rm -f "$BASE/warp-gateway.json"; fi
  if [[ -f $saved/unit ]]; then cp "$saved/unit" "$SYSTEMD_DIR/skybyte-warp-gateway.service"; else systemctl disable skybyte-warp-gateway.service || :; rm -f "$SYSTEMD_DIR/skybyte-warp-gateway.service"; fi
  systemctl daemon-reload || :; [[ $active != true ]] || systemctl start skybyte-warp-gateway.service || :
  rm -rf "$saved"; err "$(L '网关验证失败，已恢复此前网关' 'Gateway verification failed; previous gateway restored')"; return 1
 fi
 rm -rf "$saved"; domains=$(warp_engine defaults) || return 1
 warp_switch "$routing" "$port" "$udp" "$domains"
}
warp_dualstack(){
 local port trace family ips ip
 port=$(warp_engine port) && warp_verify "$port" || return 1
 say '测试 WARP 的 IPv4/IPv6 TCP 出口，不代表系统全局双栈或平台解锁。' 'Tests WARP IPv4/IPv6 TCP egress, not system-wide dual-stack or service unlocking.'
 for family in A AAAA; do
  ips=$(curl -q -fsSL --noproxy '*' --max-time 12 --proto '=https' "https://cloudflare-dns.com/dns-query?name=www.cloudflare.com&type=$family" -H 'accept: application/dns-json' | python3 -c 'import ipaddress,json,sys; kind=1 if sys.argv[1]=="A" else 28; print("\n".join(str(ipaddress.ip_address(a["data"])) for a in json.load(sys.stdin).get("Answer",[]) if a.get("type")==kind and ipaddress.ip_address(a["data"]).is_global))' "$family") || { warn "$(L 'DNS 查询失败，能力未知' 'DNS query failed; capability unknown')"; continue; }
  ip=${ips%%$'\n'*}; [[ -n $ip ]] || { warn "$family: $(L '无目标地址' 'No target address')"; continue; }
  if [[ $family == AAAA ]]; then ip="[$ip]"; fi
  trace=$(curl -q -fsSL --noproxy '' --proxy "socks5h://127.0.0.1:$port" --proto '=https' --max-time 12 --max-filesize 65536 --connect-to "www.cloudflare.com:443:$ip:443" https://www.cloudflare.com/cdn-cgi/trace) || { warn "$family: $(L '连接失败，能力未验证' 'Connection failed; capability unverified')"; continue; }
  if printf '%s\n' "$trace" | python3 -c 'import ipaddress,sys; d=dict(line.strip().split("=",1) for line in sys.stdin if "=" in line); family=4 if sys.argv[1]=="A" else 6; sys.exit(0 if d.get("warp") in ("on","plus") and ipaddress.ip_address(d["ip"]).version==family else 1)' "$family"; then ok "$family: $(L 'WARP 出口通过' 'WARP egress passed')"; else warn "$family: $(L '未验证为 WARP 出口' 'Not verified as WARP egress')"; fi
 done
}
warp_remove(){
 warp_guard || return 1
 if [[ -f $SYSTEMD_DIR/skybyte-warp-gateway.service ]]; then systemctl disable --now skybyte-warp-gateway.service || return 1; rm -f "$SYSTEMD_DIR/skybyte-warp-gateway.service"; fi
 if [[ -f $BASE/warp-client.json ]] && command -v warp-cli >/dev/null; then
  local current expected
  current=$(warp-cli --accept-tos registration show | sha256sum | awk '{print $1}') || current=''
  expected=$(python3 -c 'import json,sys; d=json.load(open(sys.argv[1])); assert d["owner"]=="SKYBYTE WARP client v1"; print(d["registration_hash"])' "$BASE/warp-client.json") || return 1
  if [[ -n $current && $current == "$expected" ]]; then warp-cli --accept-tos disconnect || return 1; else warn "$(L 'WARP 注册已改变，保留客户端连接' 'WARP registration changed; client connection retained')"; fi
 fi
 rm -f "$BASE/warp-state.json" "$BASE/warp-gateway.json" "$BASE/warp-client.json"
}
warp_restore_snapshot(){
 local path=$1 active=false
 warp_guard || return 1
 if [[ -f $SYSTEMD_DIR/skybyte-warp-gateway.service ]] && systemctl is-active --quiet skybyte-warp-gateway.service; then active=true; systemctl stop skybyte-warp-gateway.service || return 1; fi
 warp_engine restore "$path" || return 1
 if [[ -f $path/warp-gateway.json ]]; then
  [[ -f $path/warp-gateway.unit && ! -L $path/warp-gateway.json && ! -L $path/warp-gateway.unit ]] || return 1
  grep -Fxq 'Description=SKYBYTE managed WARP gateway' "$path/warp-gateway.unit" && grep -Fxq "ExecStart=$BIN run -c $BASE/warp-gateway.json" "$path/warp-gateway.unit" || return 1
  "$BIN" check -c "$path/warp-gateway.json" || return 1
  cp "$path/warp-gateway.json" "$BASE/warp-gateway.json" && cp "$path/warp-gateway.unit" "$SYSTEMD_DIR/skybyte-warp-gateway.service" || return 1
  systemctl daemon-reload || return 1
  if [[ $active == true || ( -f $path/warp-gateway-active && $(cat "$path/warp-gateway-active") == true ) ]]; then systemctl enable --now skybyte-warp-gateway.service || return 1; fi
 elif [[ -f $SYSTEMD_DIR/skybyte-warp-gateway.service ]]; then
  systemctl disable --now skybyte-warp-gateway.service || return 1
  rm -f "$SYSTEMD_DIR/skybyte-warp-gateway.service" "$BASE/warp-gateway.json";systemctl daemon-reload || return 1
 fi
}
warp_reconcile(){
 [[ -f $BASE/warp-state.json ]] || return 0
 warp_engine reconcile
}

