 if [[ $# == 0 || $1 == --menu ]]; then
 printf '\n%s%s%s\n' "$CYAN" "$(L '========== WARP 管理 ==========' '========== WARP Manager ==========')" "$RESET"
 warp_engine status "${LANGUAGE_CHOICE:-zh_CN}" || return 1
 prompt_options '
