  [[ ! -L $unit ]] && grep -Fxq 'Description=sing-box (managed by singbox-v2)' "$unit" && grep -Fxq "ExecStart=$BIN run -c $CONF" "$unit" || return 1
 fi
}
configuration_engine(){
