  2) method=cloudflare;; *) return 1;;
 esac
 say '申请公开证书会公开域名；请阅读并同意 CA 条款 https://letsencrypt.org/repository/ 。DNS Token 需仅授权对应区域 DNS 编辑。' 'Public issuance publishes the domain. Review CA terms: https://letsencrypt.org/repository/ . Scope DNS tokens to the target zone.'
 confirm "$(L '接受 CA 条款并申请证书？' 'Accept CA terms and request certificate?')" || return 0
 apt_install certbot || return 1
 if [[ $method == cloudflare ]];then apt_install python3-certbot-dns-cloudflare || return 1;fi
 mkdir -m 700 "$BASE/acme" || return 1
 printf 'SKYBYTE ACME v1\n' > "$BASE/acme/.skybyte-owner"
 acme_options
 local -a challenge=(--standalone)
 if [[ $method == cloudflare ]];then
  prompt_read "$(L 'Cloudflare DNS API Token（隐藏）：' 'Cloudflare DNS API Token (hidden): ')" token secret || return 1;echo
  [[ $token =~ ^[a-zA-Z0-9_-]{20,200}$ ]] || return 1
  printf 'dns_cloudflare_api_token = %s\n' "$token" > "$BASE/acme/cloudflare.ini";chmod 600 "$BASE/acme/cloudflare.ini";unset token
  challenge=(--dns-cloudflare --dns-cloudflare-credentials "$BASE/acme/cloudflare.ini" --dns-cloudflare-propagation-seconds 60)
 else
  warn "$(L '请确认域名 A/AAAA 记录正确，且 UFW 和云安全组允许 TCP80；脚本不会停止已有网站。' 'Verify domain A/AAAA records and allow TCP80 in UFW/provider rules; existing sites are not stopped.')"
  if command -v ufw >/dev/null && LC_ALL=C ufw status | grep -q '^Status: active';then ufw allow 80/tcp || return 1;fi
 fi
 if ! certbot certonly "${ACME_ARGS[@]}" "${challenge[@]}" --non-interactive --agree-tos --email "$email" --cert-name skybyte -d "$domain" > "$BASE/acme/last-issue.log" 2>&1;then
  chmod 600 "$BASE/acme/last-issue.log";err "$(L "申请失败；私密日志：$BASE/acme/last-issue.log。可选择清理失败申请后重试。" "Issuance failed; private log: $BASE/acme/last-issue.log. Clean failed attempt before retrying.")";return 1
 fi
 cert=$BASE/acme/config/live/skybyte/fullchain.pem;key=$BASE/acme/config/live/skybyte/privkey.pem
 validate_certificate "$cert" "$key" "$domain" || return 1
 python3 - "$BASE/acme-state.json" "$domain" "$method" <<'PY_ACME_STATE'
import json,os,sys,tempfile
fd,tmp=tempfile.mkstemp(dir=os.path.dirname(sys.argv[1]))
with os.fdopen(fd,'w') as f:json.dump({'owner':'SKYBYTE ACME v1','schema':1,'domain':sys.argv[2],'method':sys.argv[3]},f)
os.replace(tmp,sys.argv[1])
PY_ACME_STATE
 ok "$(L '证书申请成功' 'Certificate issued')"
 say "证书：${cert}；私钥请勿公开。" "Certificate: $cert; keep the key private."
 acme_use_hy2
}
acme_use_hy2(){
 acme_guard && [[ -f $BASE/acme-state.json ]] || return 1
 [[ -f $CONF ]] || return 0
 if ! protocol_port hysteria2 >/dev/null 2>&1;then say 'HY2 尚未安装；可在添加 HY2 或在线订阅时使用此证书。' 'HY2 is not installed; use this certificate when adding HY2 or online subscriptions.';return 0;fi
 local domain
 domain=$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["domain"])' "$BASE/acme-state.json") || return 1
 if confirm "$(L '将托管证书用于 HY2，保留密码和用量？' 'Use managed certificate for HY2, preserving passwords and usage?')";then
  configuration_apply tls "$domain" "$BASE/acme/config/live/skybyte/fullchain.pem" "$BASE/acme/config/live/skybyte/privkey.pem" || return 1
  certificate_record "$(openssl x509 -in "$BASE/acme/config/live/skybyte/fullchain.pem" -noout -fingerprint -sha256)"
 fi
}
acme_renew(){
 acme_guard && [[ -f $BASE/acme-state.json ]] || return 1
 require_cmd certbot || return 1;acme_options
 certbot renew "${ACME_ARGS[@]}" --cert-name skybyte --non-interactive > "$BASE/acme/last-renew.log" 2>&1 || { err "$(L '续签失败，保留当前证书；检查私密日志' 'Renewal failed; current certificate retained; inspect private log')";return 1; }
 chmod 600 "$BASE/acme/last-renew.log"
 local domain cert=$BASE/acme/config/live/skybyte/fullchain.pem key=$BASE/acme/config/live/skybyte/privkey.pem
 domain=$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["domain"])' "$BASE/acme-state.json") || return 1
 validate_certificate "$cert" "$key" "$domain" || return 1
 if [[ -f $CONF ]] && [[ $(state cert_path) == "$cert" ]];then certificate_check || return 1;fi
 if [[ -f $BASE/subscriptions.json ]];then online_reload || return 1;fi
}
acme_timer(){
 acme_guard && users_guard setup && [[ -f $BASE/acme-state.json ]] || return 1
 [[ $SCRIPT_PATH -ef $MANAGER_BIN ]] || command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1
 cat > "$SYSTEMD_DIR/skybyte-acme.service" <<UNIT
[Unit]
Description=SKYBYTE managed ACME renewal
[Service]
Type=oneshot
ExecStart=/bin/bash $MANAGER_BIN --acme-renew
UMask=0077
UNIT
 cat > "$SYSTEMD_DIR/skybyte-acme.timer" <<'UNIT'
[Unit]
Description=SKYBYTE managed ACME renewal
[Timer]
OnCalendar=*-*-* 03,15:00:00
RandomizedDelaySec=1h
Persistent=true
[Install]
WantedBy=timers.target
UNIT
 if certificate_identity >/dev/null 2>&1;then certificate_check || return 1;fi
 systemctl daemon-reload && systemctl enable --now skybyte-acme.timer
}
acme_menu(){
 acme_guard || return 1
 local choice
 # --menu renders only; a numeric argument executes one selected operation.
 if [[ $# == 0 || $1 == --menu ]]; then
 prompt_options '1. 申请域名证书
2. 使用证书用于 HY2
3. 手动续签
4. 开启自动续签
5. 关闭自动续签
6. 清理未完成的申请
0. 返回' '1. Issue domain certificate
2. Use for HY2
3. Renew
4. Enable auto-renew
5. Disable auto-renew
6. Clean failed issuance
0. Back'
 [[ ${1:-} != --menu ]] || return 0
 prompt_read '> ' choice || return 0
 else
  choice=$1
 fi
 case $choice in
  1) acme_issue;;2) acme_use_hy2;;3) acme_renew;;4) acme_timer;;
  5) [[ ! -f $SYSTEMD_DIR/skybyte-acme.timer ]] || systemctl disable --now skybyte-acme.timer;;
  6) [[ ! -e $BASE/acme-state.json ]] || { err "$(L '已有成功申请，拒绝清理' 'Successful issuance exists; refusing cleanup')";return 1; }
   confirm "$(L '删除本工具未完成的 ACME 申请目录后重试？' 'Delete the incomplete managed ACME attempt for retry?')" && rm -rf "$BASE/acme";;
  0) return 0;;*) return 1;;
 esac
}

acme_remove(){
 acme_guard || return 1
 [[ ! -f $SYSTEMD_DIR/skybyte-acme.timer ]] || systemctl disable --now skybyte-acme.timer || return 1
 [[ ! -f $SYSTEMD_DIR/skybyte-acme.service ]] || systemctl stop skybyte-acme.service || return 1
 rm -f "$SYSTEMD_DIR/skybyte-acme.timer" "$SYSTEMD_DIR/skybyte-acme.service" "$BASE/acme-state.json"
 [[ ! -d $BASE/acme ]] || rm -rf "$BASE/acme"
}

online_engine(){
 local -a command=(python3)
 [[ ${1:-} != serve ]] || command=(exec python3)
 "${command[@]}" - "$BASE" "$MANAGER_BIN" "$@" <<'PY_ONLINE'
"""Private token subscriptions served over TLS. Never expose server configs or controller keys."""
import copy,hmac,http.server,json,os,pathlib,re,secrets,socket,socketserver,ssl,subprocess,sys,tempfile,threading,time,urllib.parse
OWNER='SKYBYTE HTTPS subscriptions v1'
FORMATS={'shadowrocket':'shadowrocket-native-subscription.txt','v2rayn':'v2rayn-subscription.txt','clash':'clash-verge.yaml','singbox':'sing-box-client.json'}

def atomic(p,d):
 if p.is_symlink():raise ValueError('Subscription state symlink')
 fd,tmp=tempfile.mkstemp(dir=p.parent)
 try:
  with os.fdopen(fd,'w') as f:json.dump(d,f,indent=2);f.flush();os.fsync(f.fileno())
  os.replace(tmp,p)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)

def read(base):
 p=pathlib.Path(base)/'subscriptions.json'
 if p.is_symlink():raise ValueError('Subscription state symlink')
 d=json.loads(p.read_text())
 if d.get('owner')!=OWNER or d.get('schema')!=1 or type(d['port']) is not int or not 1024<=d['port']<=65535:raise ValueError('Invalid subscription settings')
 if len(d['host'])>253 or not re.fullmatch(r'(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}',d['host']):raise ValueError('Invalid subscription hostname')
 if not isinstance(d['tokens'],dict):raise ValueError('Invalid token ledger')
 for uid,token in d['tokens'].items():
  if not re.fullmatch('[0-9a-f]{16}',uid) or token is not None and not re.fullmatch('[A-Za-z0-9_-]{43}',token):raise ValueError('Invalid subscription token')
 return d

def user(base,uid):
 path=pathlib.Path(base)/'users.json'
 if path.is_symlink() or (path.parent/'users').is_symlink():raise ValueError('User ledger symlink')
 d=json.loads(path.read_text())
 if d.get('owner')!='SKYBYTE user quotas v1' or d.get('schema')!=1:raise ValueError('Invalid user ledger')
 u=next((u for u in d['users'] if u['id']==uid and not u.get('deleted')),None)
 if u is None:raise ValueError('Account not found')
 return d,u

def authorize(base,token):
 d=read(base);uid=next((uid for uid,value in d['tokens'].items() if value and hmac.compare_digest(value,token)),None)
 if uid is None:return None
 ledger,u=user(base,uid)
 if not ledger.get('supervisor_enabled',True) or not u['enabled'] or u.get('metering_blocked') or u['expires_at']<=time.time() or u['upload']+u['download']>=u['quota_bytes']:return None
 return uid,u

def links(d,uid):
 token=d['tokens'].get(uid)
 if not token:raise ValueError('Subscription revoked or not issued')
 return {kind:'https://'+d['host']+(':'+str(d['port']) if d['port']!=443 else '')+'/s/'+token+'/'+kind for kind in FORMATS}

def handler(base,manager,exporter=None):
 base=pathlib.Path(base)
 def export(uid):
  r=subprocess.run(['/bin/bash',str(manager),'--subscription-export',uid],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=20)
  if r.returncode:raise ValueError('Export generation failed')
 export=exporter or export
 class Handler(http.server.BaseHTTPRequestHandler):
  protocol_version='HTTP/1.1';server_version='SKYBYTE';sys_version=''
  def log_message(self,*_):pass
  def setup(self):
   self.request.settimeout(10)
   if isinstance(self.request,ssl.SSLSocket):self.request.do_handshake()
   super().setup()
  def reply(self,code,payload=b'',headers=None):
   self.send_response(code);self.send_header('Content-Length',str(len(payload)));self.send_header('Cache-Control','no-store');self.send_header('Connection','close')
   for key,value in (headers or {}).items():self.send_header(key,value)
   self.end_headers();self.close_connection=True
   if self.command!='HEAD' and payload:self.wfile.write(payload)
  def do_GET(self):self.deliver()
  def do_HEAD(self):self.deliver()
  def deliver(self):
   try:
    path=urllib.parse.urlsplit(self.path)
    match=re.fullmatch(r'/s/([A-Za-z0-9_-]{43})/(shadowrocket|v2rayn|clash|singbox)',path.path)
    if not match or path.query or path.fragment:return self.reply(404)
    if not self.server.allow(self.client_address[0]):return self.reply(429)
    token,kind=match.groups();auth=authorize(base,token)
    if not auth:return self.reply(404)
    uid,_=auth
    if self.command!='HEAD':export(uid)
    auth=authorize(base,token)
    if not auth or auth[0]!=uid:return self.reply(404)
    _,u=auth;p=base/'users'/uid/FORMATS[kind]
    if p.is_symlink() or p.parent.is_symlink() or not p.is_file():return self.reply(503)
    if p.stat().st_size>8*1024*1024:return self.reply(503)
    payload=p.read_bytes()
    headers={'Content-Type':'application/json' if kind=='singbox' else 'text/yaml; charset=utf-8' if kind=='clash' else 'text/plain; charset=utf-8',
             'subscription-userinfo':'upload='+str(u['upload'])+'; download='+str(u['download'])+'; total='+str(u['quota_bytes'])+'; expire='+str(u['expires_at']),
             'X-Content-Type-Options':'nosniff','Content-Disposition':'attachment; filename="'+FORMATS[kind]+'"'}
    self.reply(200,payload,headers)
   except (ValueError,KeyError,OSError,subprocess.SubprocessError):self.reply(503)
 return Handler

class Server(socketserver.ThreadingMixIn,http.server.HTTPServer):
 daemon_threads=True;allow_reuse_address=True
 def __init__(self,*args,**kwargs):
  self.slots=threading.BoundedSemaphore(16);self.rate_lock=threading.Lock();self.rates={};super().__init__(*args,**kwargs)
 def process_request(self,request,address):
  if not self.slots.acquire(blocking=False):self.shutdown_request(request);return
  try:super().process_request(request,address)
  except BaseException:self.slots.release();raise
 def process_request_thread(self,request,address):
  try:super().process_request_thread(request,address)
  finally:self.slots.release()
 def handle_error(self,*_):pass
 def allow(self,ip):
  with self.rate_lock:
   now=time.monotonic()
   self.rates={k:v for k,v in self.rates.items() if now-v[0]<60}
   if ip not in self.rates and len(self.rates)>=1024:return False
   start,count=self.rates.get(ip,(now,0));self.rates[ip]=(start,count+1);return count<60
 def get_request(self):
  request,address=self.socket.accept();request.settimeout(10)
  return (self.context.wrap_socket(request,server_side=True,do_handshake_on_connect=False),address) if hasattr(self,'context') else (request,address)

class DualServer(Server):
 address_family=socket.AF_INET6
 def server_bind(self):self.socket.setsockopt(socket.IPPROTO_IPV6,socket.IPV6_V6ONLY,0);super().server_bind()

def serve(base,manager):
 d=read(base);context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER);context.minimum_version=ssl.TLSVersion.TLSv1_2;context.load_cert_chain(d['cert'],d['key'])
 try:server=DualServer(('::',d['port']),handler(base,manager))
 except OSError:server=Server(('0.0.0.0',d['port']),handler(base,manager))
 server.context=context
 with server:server.serve_forever(poll_interval=.5)

if __name__=='__main__':
 base,manager,action,*args=sys.argv[1:];base=pathlib.Path(base);p=base/'subscriptions.json'
 if action=='serve':serve(base,manager)
 elif action=='guard':
  if p.exists():read(base)
 elif action=='init':
  if p.exists() or p.is_symlink():raise ValueError('Subscription settings already exist')
  host,port,cert,key=args;d={'owner':OWNER,'schema':1,'host':host,'port':int(port),'cert':cert,'key':key,'tokens':{}};atomic(p,d)
  try:read(base)
  except BaseException:p.unlink();raise
 elif action in ('issue','revoke','links'):
  d=read(base);uid=args[0];user(base,uid)
  if action=='issue':d['tokens'][uid]=secrets.token_urlsafe(32);atomic(p,d)
  elif action=='revoke':d['tokens'][uid]=None;atomic(p,d)
  if action!='revoke':
   for kind,url in links(d,uid).items():print(kind+'\n'+url+'\n'+'-'*64)
 else:raise ValueError('Unknown subscription operation')
PY_ONLINE
}
online_guard(){
 local unit=$SYSTEMD_DIR/skybyte-subscriptions.service
 [[ ! -L $BASE/subscriptions.json ]] || return 1
 if [[ -e $unit || -L $unit ]];then
  [[ ! -L $unit ]] && grep -Fxq 'Description=SKYBYTE managed HTTPS subscriptions' "$unit" && grep -Fxq "ExecStart=/bin/bash $MANAGER_BIN --subscription-serve" "$unit" || return 1
 fi
 online_engine guard
}
online_setup(){
 check_owned && users_guard setup && online_guard || return 1
 local host port cert key
 [[ ! -e $BASE/subscriptions.json ]] || { err "$(L '订阅服务已配置，请使用状态、重载或停用' 'Subscription service configured; use status/reload/disable')";return 1; }
 prompt_read "$(L '订阅域名（DNS指向本机）：' 'Subscription hostname (DNS points here): ')" host || return 0
 prompt_read "$(L 'HTTPS 端口 [8443]：' 'HTTPS port [8443]: ')" port || return 0;port=${port:-8443}
 valid_port "$port" && ((10#$port>=1024)) || return 1
 haproxy_engine check_port "$port" || return 1
 if ss -H -ltn "( sport = :$port )" | grep -q .;then err "$(L '端口已占用' 'Port occupied')";return 1;fi
 prompt_read "$(L '可信 TLS 完整证书路径（回车用托管 ACME）：' 'Trusted TLS fullchain (Enter for managed ACME): ')" cert || return 0
 prompt_read "$(L 'TLS 私钥路径（回车用托管 ACME）：' 'TLS private key (Enter for managed ACME): ')" key || return 0
 cert=${cert:-$BASE/acme/config/live/skybyte/fullchain.pem};key=${key:-$BASE/acme/config/live/skybyte/privkey.pem}
 validate_certificate "$cert" "$key" "$host" || return 1
 if [[ $(openssl x509 -in "$cert" -noout -issuer -nameopt RFC2253) == "issuer=$(openssl x509 -in "$cert" -noout -subject -nameopt RFC2253 | sed 's/^subject=//')" ]];then
  err "$(L '在线订阅需要客户端信任的域名证书；请先申请 ACME，拒绝默认使用自签名' 'Online subscriptions require a client-trusted domain certificate; issue ACME first; self-signed is not used by default')";return 1
 fi
 online_chain_check "$cert" || { err "$(L '证书链未通过系统信任验证' 'Certificate chain did not pass system trust validation')";return 1; }
 confirm "$(L '开启公开 HTTPS 服务，仅通过独立 Token 返回个人客户端配置？' 'Enable public HTTPS delivery of personal client configs through independent tokens?')" || return 0
 [[ $SCRIPT_PATH -ef $MANAGER_BIN ]] || command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1
 online_engine init "$host" "$port" "$cert" "$key" || return 1
 cat > "$SYSTEMD_DIR/skybyte-subscriptions.service" <<UNIT
[Unit]
Description=SKYBYTE managed HTTPS subscriptions
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=/bin/bash $MANAGER_BIN --subscription-serve
Restart=on-failure
RestartSec=5
KillMode=mixed
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
[Install]
WantedBy=multi-user.target
UNIT
 if ! systemctl daemon-reload || ! systemctl enable --now skybyte-subscriptions.service || ! { sleep 2;systemctl is-active --quiet skybyte-subscriptions.service; };then
  systemctl disable --now skybyte-subscriptions.service || :;rm -f "$SYSTEMD_DIR/skybyte-subscriptions.service" "$BASE/subscriptions.json";systemctl daemon-reload || :;return 1
 fi
 if command -v ufw >/dev/null && LC_ALL=C ufw status | grep -q '^Status: active';then ufw allow "$port/tcp" || return 1;fi
 say "请在云防火墙放行 TCP ${port}。" "Allow TCP $port in the provider firewall."
 ok "$(L 'HTTPS 订阅服务已开启；在用户菜单签发个人订阅' 'HTTPS subscriptions enabled; issue personal links in user management')"
}
online_reload(){
 online_guard || return 1
 [[ -f $BASE/subscriptions.json ]] || return 0
 local cert key host
 { IFS= read -r cert;IFS= read -r key;IFS= read -r host; } < <(python3 - "$BASE/subscriptions.json" <<'PY_ONLINE_TLS'
import json,sys
s=json.load(open(sys.argv[1]));print(s['cert']);print(s['key']);print(s['host'])
PY_ONLINE_TLS
 )
 validate_certificate "$cert" "$key" "$host" || return 1
 if systemctl is-active --quiet skybyte-subscriptions.service;then systemctl restart skybyte-subscriptions.service && systemctl is-active --quiet skybyte-subscriptions.service;fi
}
online_remove(){
 online_guard || return 1
 if [[ -f $SYSTEMD_DIR/skybyte-subscriptions.service ]];then systemctl disable --now skybyte-subscriptions.service || return 1;rm -f "$SYSTEMD_DIR/skybyte-subscriptions.service";fi
 if [[ -f $BASE/subscriptions.json ]] && python3 - "$BASE" <<'PY_SUB_OWNED_CERT'
import json,pathlib,sys
base=pathlib.Path(sys.argv[1]);s=json.loads((base/'subscriptions.json').read_text())
sys.exit(0 if s['cert']==str(base/'subscription-backup.crt') and s['key']==str(base/'subscription-backup.key') else 1)
PY_SUB_OWNED_CERT
 then
  rm -f "$BASE/subscription-backup.crt" "$BASE/subscription-backup.key"
 fi
 rm -f "$BASE/subscriptions.json"
}
online_user(){
 users_guard && online_guard || return 1
 [[ -f $BASE/subscriptions.json ]] || { err "$(L '请先在节点与订阅菜单配置 HTTPS 服务' 'Configure HTTPS delivery in Nodes/subscriptions first')";return 1; }
 local id choice
 users_engine list;prompt_read "$(L '用户 ID：' 'Account ID: ')" id || return 0
 prompt_options '1. 签发 / 重置独立 Token
2. 查看个人订阅
3. 撤销 Token
0. 返回' '1. Issue / rotate independent token
2. View personal links
3. Revoke token
0. Back'
 prompt_read '> ' choice || return 0
 case $choice in
  1) confirm "$(L '签发新 Token？旧订阅地址将立即失效。' 'Issue new token? Previous subscription URL becomes invalid.')" && { printf '%s' "$RED";online_engine issue "$id";local rc=$?;printf '%s' "$RESET";return "$rc"; };;
  2) printf '%s' "$RED";online_engine links "$id";local rc=$?;printf '%s' "$RESET";return "$rc";;
  3) confirm "$(L '撤销个人在线订阅地址？节点凭据不变。' 'Revoke personal online subscription URL? Node credentials stay unchanged.')" && online_engine revoke "$id";;
  0) return 0;;*) return 1;;
 esac
}
online_menu(){
 online_guard || return 1
 local choice
 # --menu renders only; a numeric argument executes one selected operation.
 if [[ $# == 0 || $1 == --menu ]]; then
 prompt_options '1. 配置 HTTPS 服务
2. 服务状态
3. 启动
4. 停止
5. 重载证书
6. 用户订阅 Token
0. 返回' '1. Configure HTTPS
2. Status
3. Start
4. Stop
5. Reload certificate
6. Account tokens
0. Back'
 [[ ${1:-} != --menu ]] || return 0
 prompt_read '> ' choice || return 0
 else
  choice=$1
 fi
 case $choice in
  1) online_setup;;2) systemctl --no-pager status skybyte-subscriptions.service || :;;
  3) [[ -f $BASE/subscriptions.json && -f $SYSTEMD_DIR/skybyte-subscriptions.service ]] && systemctl enable --now skybyte-subscriptions.service;;
  4) [[ ! -f $SYSTEMD_DIR/skybyte-subscriptions.service ]] || systemctl disable --now skybyte-subscriptions.service;;
  5) online_reload;;6) online_user;;0) return 0;;*) return 1;;
 esac
}

online_chain_check(){ openssl verify -purpose sslserver -untrusted "$1" "$1" >/dev/null 2>&1; }
auxiliary_restore_snapshot() (
 local path=$1 host cert key created=false aux_acme=false aux_online=false aux_unit=false aux_success=false
 trap auxiliary_restore_cleanup EXIT
 acme_guard && online_guard || return 1
 # Keep live certificate-account/DNS state and current tokens; only fill absent state.
 if [[ ! -e $BASE/acme-state.json && ! -e $BASE/acme && -f $path/acme-state.json && -d $path/acme ]];then
  [[ ! -L $path/acme ]] && grep -Fxq 'SKYBYTE ACME v1' "$path/acme/.skybyte-owner" || return 1
  aux_acme=true
  cp -a "$path/acme" "$BASE/acme" && cp "$path/acme-state.json" "$BASE/acme-state.json" || return 1
  acme_guard || return 1
 fi
 if [[ ! -e $BASE/subscriptions.json && -f $path/subscriptions.json ]];then
  for cert in subscription-backup.crt subscription-backup.key;do [[ -f $path/$cert && ! -L $path/$cert && ! -e $BASE/$cert && ! -L $BASE/$cert ]] || return 1;done
  { IFS= read -r host;IFS= read -r cert;IFS= read -r key; } < <(python3 - "$path/subscriptions.json" <<'PY_SUB_RESTORE'
import json,sys
s=json.load(open(sys.argv[1]));assert s['owner']=='SKYBYTE HTTPS subscriptions v1';print(s['host']);print(s['cert']);print(s['key'])
PY_SUB_RESTORE
 )
  [[ $cert == "$BASE/subscription-backup.crt" && $key == "$BASE/subscription-backup.key" ]] || return 1
  validate_certificate "$path/subscription-backup.crt" "$path/subscription-backup.key" "$host" && online_chain_check "$path/subscription-backup.crt" || return 1
  aux_online=true
  cp "$path/subscription-backup.crt" "$cert" && cp "$path/subscription-backup.key" "$key" && cp "$path/subscriptions.json" "$BASE/subscriptions.json" || return 1
  chmod 600 "$cert" "$key" "$BASE/subscriptions.json";created=true
  if [[ -f $path/subscriptions.unit ]];then
   grep -Fxq 'Description=SKYBYTE managed HTTPS subscriptions' "$path/subscriptions.unit" && grep -Fxq "ExecStart=/bin/bash $MANAGER_BIN --subscription-serve" "$path/subscriptions.unit" || return 1
   users_guard setup || return 1
   [[ $SCRIPT_PATH -ef $MANAGER_BIN ]] || command install -m 700 "$SCRIPT_PATH" "$MANAGER_BIN" || return 1
   aux_unit=true
   cp "$path/subscriptions.unit" "$SYSTEMD_DIR/skybyte-subscriptions.service" || return 1
   online_guard && systemctl daemon-reload || return 1
   if [[ -f $path/subscriptions.active && $(cat "$path/subscriptions.active") == true ]];then systemctl enable --now skybyte-subscriptions.service && systemctl is-active --quiet skybyte-subscriptions.service || return 1;fi
  fi
 fi
 if [[ $created == true ]];then say '已恢复缺失的 HTTPS订阅；现有Token未覆盖。ACME自动续签需重新启用并确认关联路径。' 'Missing HTTPS subscriptions restored; existing tokens preserved. Re-enable ACME renewal after checking path association.';fi
 aux_success=true
)
auxiliary_restore_cleanup(){
 [[ ${aux_success:-false} != true ]] || return 0
 if [[ ${aux_unit:-false} == true ]];then systemctl disable --now skybyte-subscriptions.service || :;rm -f "$SYSTEMD_DIR/skybyte-subscriptions.service";systemctl daemon-reload || :;fi
 if [[ ${aux_online:-false} == true ]];then rm -f "$BASE/subscriptions.json" "$BASE/subscription-backup.crt" "$BASE/subscription-backup.key";fi
 if [[ ${aux_acme:-false} == true ]];then rm -f "$BASE/acme-state.json";rm -rf "$BASE/acme";fi
}

usage_help(){
 printf '%s' "$YELLOW"
 if [[ ${LANGUAGE_CHOICE:-zh_CN} == en_US ]];then cat <<'HELP_EN'
SKYBYTE Manager — quick guide
1. Install: main a → Reality/HY2/both. Enter defaults, allow actual TCP/UDP ports in provider firewall.
2. Node edits: main a → 5. Change admin ports/address/SNI or add/remove a protocol without resetting credentials/usage. Active hopping is disabled after edits; re-enable it for the current listener.
3. Client import: main b → 1 or 4. Use Shadowrocket native links/QR, v2rayN, full Mihomo YAML or sing-box JSON. Self-signed HY2 needs explicit public-certificate trust; never share private keys.
4. Accounts: main g. Initialize, create accounts and set quota/expiry. Share personal exports, not administrator nodes. Accounts are not actual people and may share credentials.
5. HTTPS subscriptions: obtain a trusted certificate through main e → 6, then main b → 6. Create/rotate/revoke personal links through user menu 16. Configure provider TCP access. Tokens grant access to credentials: keep links private. Revocation does not rotate node passwords.
6. Certificates: main e → 6 issues isolated ACME/Certbot certificates using HTTP-01 or Cloudflare DNS-01; auto-renew is opt-in. HTTP requires public TCP80. DNS tokens remain private. Existing websites/certificates are preserved.
7. WARP/media: main d → 9 / 8. WARP defaults to selected media/AI domains. It cannot guarantee location or unlocking. Anonymous tests do not verify playback. WARP menu 6 maintains catalogs; applying them is a separate confirmation.
8. Backup: main e → 2 creates a backup; 3 restores it; 7 lists/preflights/encrypts/imports or explicitly prunes old backups. Backups contain keys. Restore keeps current usage/policies and current subscription tokens.
9. Versions: main e → 1 selects this release's tested core, latest stable or a specific version/downgrade. Every managed config must validate; weekly auto-update remains removed.
10. Resources: main d → 7. Each account uses a core. Capacity depends on measured memory/CPU/traffic. Account quotas are periodically enforced, not byte-exact billing.
11. Residential landing / VPS relay: main d → 10, then 6 for step-by-step help. Import one Reality/Vision or HY2 landing URI/JSON. Clients connect to this VPS and destinations see the landing exit. Self-signed HY2 requires trusted public certificate material. Relay and WARP are alternative routing policies; failed relay traffic has no automatic direct fallback. Measure both links before judging speed.
12. HAProxy TCP passthrough: main d → 11, then 12 for help. A may run only the TCP forwarder; B runs the authenticated Reality/Trojan node. On the phone, keep B's credentials/SNI/TLS trust and change only the address/port to A. HY2/raw UDP are unsupported. User quotas belong on B. This menu has separate backup/restore/uninstall controls; full sing-box backups include a haproxy subdirectory for separate restoration.
13. Reality target checks: main d → 12. Check configured targets or a custom hostname/port/SNI; verify DNS, TCP, TLS 1.3, certificate and HTTP/2. Read-only, with bounded network timeouts; this does not test client-to-VPS connectivity.
14. Node parameters: main b → 7 shows UUID/public key/short ID/SNI. Important data is stored on this VPS: keep it private and install/enable a firewall through d → 2 after allowing SSH and node ports.
15. Installation checks: main a → 7. New installs and Reality additions run preflight checks; local binds do not prove public inbound access. The short HTTPS install entry is sky9119.cc/sb.sh.
CLI: --help, --self-check. Maintenance flags are used by owned systemd services.
HELP_EN
 else cat <<'HELP_ZH'
SKYBYTE Manager — 快速使用说明
1. 安装：主菜单 a 选择 Reality、HY2或双协议。回车使用默认值，云安全组需放行实际 TCP/UDP 端口。
2. 节点修改：主菜单a → 5，可改管理员端口、地址、SNI或增删协议，保留凭据与用量。修改后已启用的跳跃会关闭，请按当前监听端口重新开启。
3. 导入客户端：主菜单b → 1或4，提供小火箭专用链接/二维码、v2rayN、完整 Mihomo YAML与sing-box JSON。自签名 HY2 须信任公开证书；不要分享私钥。
4. 用户管理：主菜单g，初始化后添加用户并设额度/有效期。只分享个人节点，不要分享管理员节点；账户数量不代表真实人数，无法阻止凭据分享。
5. 在线订阅：主菜单e → 6获取可信证书，再通过主菜单b → 6配置HTTPS服务。用户菜单16签发、重置、撤销个人链接。云安全组需允许订阅 TCP 端口。Token可获取节点凭据，链接请保密；撤销订阅不等于更换节点密码。
6. 证书：主菜单e → 6，用隔离的 ACME/Certbot 目录通过 HTTP-01 或 Cloudflare DNS-01申请，自动续签需手动开启。HTTP须公网 TCP80可达，DNS Token私密保存，不停止已有网站、不覆盖外部证书。
7. WARP/流媒体：主菜单d → 9 / 8。WARP默认仅所选流媒体和AI域名，不能保证国家或解锁；匿名检测不验证播放。WARP菜单6维护规则列表，应用新列表需单独确认。
8. 备份：主菜单e → 2新建、3恢复、7列表/预检/加密导出/导入/确认清理旧备份。备份含私钥。恢复保留当前用量、策略和当前订阅Token。
9. 版本：主菜单e → 1选本版测试内核、最新稳定版或指定版本/降级，须检查全部托管配置。每周自动更新保持移除。
10. 资源：主菜单d → 7，每个用户一个内核，容量需实测。配额周期检查，不是精确计费。
11. 住宅落地 / VPS 中转：主菜单d → 10，再选6查看具体步骤，导入一个 Reality/Vision 或 HY2 落地链接/JSON。客户端连接本 VPS，网站看到落地出口。自签名 HY2 须提供可信公开证书；中转与 WARP 分流择一启用，中转失败不自动直连。速度需按两段链路实测。
12. HAProxy TCP 透传：主菜单d → 11，再选12查看说明。A 可只运行 TCP 转发，B 运行带认证的 Reality/Trojan 节点；手机保留 B 的认证、SNI及TLS验证，仅改连接地址和端口为 A。不支持 HY2/原生UDP。配额在 B 管理。本菜单可单独备份、恢复与卸载，完整 sing-box 备份中的 haproxy 子目录需单独恢复。
13. Reality 握手检测：主菜单 d → 12。检测当前目标或自定义域名/端口/SNI；检查 DNS、TCP、TLS 1.3、证书和 HTTP/2。只读且有网络超时，不代表客户端到 VPS 已连通。
14. 节点参数：主菜单 b → 7 查看 UUID、公钥、Short ID 和 SNI。重要数据保存在本 VPS，请做好保密；务必通过 d → 2 安装并启用防火墙，先放行 SSH 和实际节点端口。
15. 安装前检测：主菜单 a → 7；新装及追加 Reality 会自动检查。端口可绑定不等于公网入站连通；短安装入口为 sky9119.cc/sb.sh。
命令行：--help、--self-check。维护参数供本工具的 systemd 服务使用。
HELP_ZH
 fi
 printf '%s' "$RESET"
}

manager_self_check(){
 python3 - "$SCRIPT_PATH" <<'PY_SELF_CHECK'
import pathlib,re,sys
s=pathlib.Path(sys.argv[1]).read_text()
for m in re.finditer(r"<<'(PY[^']*)'\n(.*?)\n\1(?:\n|$)",s,re.S):compile(m[2],m[1],'exec')
m=re.search(r'^MANAGER_VERSION=([0-9]+\.[0-9]+\.[0-9]+)$',s,re.M);assert m
assert '# SKYBYTE Manager V2.1 community manager;' in s
print(m[1])
PY_SELF_CHECK
}
